DG.put("rudr-avtaar/28",{"n":28,"title":"ਅਥ ਨ੍ਰਿਪ ਬਿਬੇਕ ਦੇ ਦਲ ਕਥਨੰ","title_roman":"Ath nrip bibek de dal kathnan","page":898,"blocks":[{"type":"heading","kind":"chhand","name":"ਛਪਯ ਛੰਦ","gurmukhi":"ਛਪਯ ਛੰਦ","roman":"Chhapay chhand","meaning_en":"Chhappay metre.","page":898,"meaning_status":"draft"},{"type":"verse","number":[228],"number_text":"੨੨੮।","page":898,"lines":[{"gurmukhi":"ਜਿਹ ਪ੍ਰਕਾਰ ਅਬਿਬੇਕ ਨ੍ਰਿਪਤਿ ਦਲ ਸਹਿਤ ਬਖਾਨੇ।","roman":"Jih prakaar abibek nripti dal sahit bakhaane |","meaning_en":"'Just as you described King Abibek (Non-discernment) with his army,","page":898,"meaning_status":"draft","note":"Speaker inferred: King Parasnath addressing the sage (Machhindra)."},{"gurmukhi":"ਨਾਮ ਠਾਮ ਆਭਰਨ ਸੁ ਰਥ ਸਭ ਕੇ ਹਮ ਜਾਨੇ।","roman":"Naam thaam aabhran su rath sabh ke ham jaane |","meaning_en":"and we came to know the names, places, ornaments and chariots of them all,","page":898,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਅਰੁ ਧਨੁਖ ਧੁਜਾ ਜਿਹ ਬਰਣ ਉਚਾਰੀ।","roman":"Sasatr asatr aru dhanukh dhujaa jih baran uchaaree |","meaning_en":"the weapons, missiles, bows and banners, whose colours you told,","page":898,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦ ਮੁਨਿ ਦੇਵ ਸਕਲ ਸੁ ਬਿਬੇਕ ਬਿਚਾਰੀ।","roman":"Tvaprasaad muni dev sakal su bibek bichaaree |","meaning_en":"and by your grace, divine sage, I have considered it all with discernment,","page":898,"meaning_status":"draft","note":"ਸਕਲ ਸੁ ਬਿਬੇਕ ਬਿਚਾਰੀ: could also mean 'now consider all of Bibek'; uncertain."},{"gurmukhi":"ਕਰਿ ਕ੍ਰਿਪਾ ਸਕਲ ਜਿਹ ਬਿਧਿ ਕਹੇ ਤਿਹ ਬਿਧਿ ਵਹੈ ਬਖਾਨੀਐ।","roman":"Kari kripaa sakal jih bidhi kahe tih bidhi vahai bakhaaneeai |","meaning_en":"be gracious and tell in the same way as you told all that:","page":898,"meaning_status":"draft"},{"gurmukhi":"ਕਿਹ ਛਬਿ ਪ੍ਰਭਾਵ ਕਿਹ ਦੁਤਿ ਨ੍ਰਿਪਤਿ ਨ੍ਰਿਪ ਬਿਬੇਕ ਅਨੁਮਾਨੀਐ। ੨੨੮।","roman":"Kih chhabi prabhaav kih duti nripti nrip bibek anumaaneeai | 228 |","meaning_en":"with what beauty, influence and splendour King Bibek (Discernment) is to be pictured.'","page":898,"meaning_status":"draft"}]},{"type":"verse","number":[229],"number_text":"੨੨੯।","page":898,"lines":[{"gurmukhi":"ਅਧਿਕ ਨ੍ਯਾਸ ਮੁਨਿ ਕੀਨ ਮੰਤ੍ਰ ਬਹੁ ਭਾਤਿ ਉਚਾਰੇ।","roman":"Adhik nyaas muni keen mantr bahu bhaati uchaare |","meaning_en":"The sage performed much nyas and recited mantras in many ways;","page":898,"meaning_status":"draft","note":"ਨ੍ਯਾਸ: ritual placing of mantras on the limbs."},{"gurmukhi":"ਤੰਤ੍ਰ ਭਲੀ ਬਿਧਿ ਸਧੇ ਜੰਤ੍ਰ ਬਹੁ ਬਿਧਿ ਲਿਖਿ ਡਾਰੇ।","roman":"Tantr bhalee bidhi sadhe jantr bahu bidhi likhi daare |","meaning_en":"he practised tantras in the proper way and wrote out yantras of many kinds;","page":898,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪਵਿਤ੍ਰ ਹੁਐ ਆਪ ਬਹੁਰਿ ਉਚਾਰ ਕਰੋ ਤਿਹ।","roman":"Ati pavitr huai aap bahuri uchaar karo tih |","meaning_en":"becoming utterly pure himself, he then spoke of it,","page":898,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਬਿਬੇਕ ਅਬਿਬੇਕ ਸਹਿਤ ਸੈਨ ਕਥ੍ਯੋ ਜਿਹ।","roman":"Nrip bibek abibek sahit sain kathyo jih |","meaning_en":"telling of King Bibek with his army as he had told of Abibek.","page":898,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰ ਅਸੁਰ ਚਕ੍ਰਿਤ ਚਹੁ ਦਿਸ ਭਏ ਅਨਲ ਪਵਨ ਸਸਿ ਸੂਰ ਸਬ।","roman":"Sur asur chakrit chahu dis bhae anal pavan sasi soor sab |","meaning_en":"Gods and demons on all four sides were astonished, and fire, wind, moon and sun all,","page":898,"meaning_status":"draft"},{"gurmukhi":"ਕਿਹ ਬਿਧਿ ਪ੍ਰਕਾਸ ਕਰਿ ਹੈ ਸੰਘਾਰ ਜਕੇ ਜਛ ਗੰਧਰਬ ਸਬ। ੨੨੯।","roman":"Kih bidhi prakaas kari hai sanghaar jake jachh gandhrab sab | 229 |","meaning_en":"wondering how he would tell of the slaughter; all the Yakshas and Gandharvas were stunned.","page":898,"meaning_status":"draft"}]},{"type":"verse","number":[230],"number_text":"੨੩੦।","page":898,"lines":[{"gurmukhi":"ਸੇਤ ਛਤ੍ਰ ਸਿਰ ਧਰੈ ਸੇਤ ਬਾਜੀ ਰਥ ਰਾਜਤ।","roman":"Set chhatr sir dharai set baajee rath raajat |","meaning_en":"He bears a white canopy over his head; white horses grace his chariot;","page":898,"meaning_status":"draft","note":"Verses 230-231 describe King Bibek."},{"gurmukhi":"ਸੇਤ ਸਸਤ੍ਰ ਤਨ ਸਜੇ ਨਿਰਖਿ ਸੁਰ ਨਰ ਭ੍ਰਮਿ ਭਾਜਤ।","roman":"Set sasatr tan saje nirkhi sur nar bhrami bhaajat |","meaning_en":"white weapons adorn his body; seeing him, gods and men flee in confusion;","page":898,"meaning_status":"draft"},{"gurmukhi":"ਚੰਦ ਚਕ੍ਰਿਤ ਹ੍ਵੈ ਰਹਤ ਭਾਨੁ ਭਵਤਾ ਲਖਿ ਭੁਲਤ।","roman":"Chand chakrit hvai rahat bhaanu bhavtaa lakhi bhulat |","meaning_en":"the moon stays astonished, and the sun, seeing his majesty, loses its way;","page":898,"meaning_status":"draft"},{"gurmukhi":"ਭ੍ਰਮਰ ਪ੍ਰਭਾ ਲਖਿ ਭ੍ਰਮਤ ਅਸੁਰ ਸੁਰ ਨਰ ਡਗ ਡੁਲਤ।","roman":"Bhramar prabhaa lakhi bhramat asur sur nar dag dulat |","meaning_en":"seeing his radiance the black bees wander confused, and demons, gods and men tremble.","page":898,"meaning_status":"draft","note":"ਭ੍ਰਮਰ: 'black bee'; uncertain why bees are named."},{"gurmukhi":"ਇਹ ਛਬਿ ਬਿਬੇਕ ਰਾਜਾ ਨ੍ਰਿਪਤਿ ਅਤਿ ਬਲਿਸਟ ਤਿਹ ਮਾਨੀਐ।","roman":"Ih chhabi bibek raajaa nripti ati balisat tih maaneeai |","meaning_en":"Such is the splendour of King Bibek, lord of kings; know him to be exceedingly mighty.","page":898,"meaning_status":"draft"},{"gurmukhi":"ਮੁਨਿ ਗਨ ਮਹੀਪ ਬੰਦਤ ਸਕਲ ਤੀਨਿ ਲੋਕਿ ਮਹਿ ਜਾਨੀਐ। ੨੩੦।","roman":"Muni gan maheep bandat sakal teeni loki mahi jaaneeai | 230 |","meaning_en":"Hosts of sages and kings all bow to him; he is known in the three worlds.","page":898,"meaning_status":"draft"}]},{"type":"verse","number":[231],"number_text":"੨੩੧।","page":898,"lines":[{"gurmukhi":"ਚਮਰ ਚਾਰੁ ਚਹੂੰ ਓਰ ਢੁਰਤ ਸੁੰਦਰ ਛਬਿ ਪਾਵਤ।","roman":"Chamar chaaru chahoon or dhurat sundar chhabi paavat |","meaning_en":"Lovely whisks wave on all four sides, giving a beautiful look;","page":898,"meaning_status":"draft","note":"ਚਮਰ: the royal fly-whisk."},{"gurmukhi":"ਨਿਰਖਿ ਹੰਸ ਤਿਹ ਢੁਰਨਿ ਮਾਨ ਸਰਵਰਹਿ ਲਜਾਵਤ।","roman":"Nirkhi hans tih dhurni maan sarvarhi lajaavat |","meaning_en":"seeing them wave, the swans of Mansarovar feel shamed;","page":898,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪਵਿਤ੍ਰ ਸਬ ਗਾਤ ਪ੍ਰਭਾ ਅਤਿ ਹੀ ਜਿਹ ਸੋਹਤ।","roman":"Ati pavitr sab gaat prabhaa ati hee jih sohat |","meaning_en":"his whole body is utterly pure, and his radiance shines splendidly;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰ ਨਰ ਨਾਗ ਸੁਰੇਸ ਜਛ ਕਿੰਨਰ ਮਨ ਮੋਹਤ।","roman":"Sur nar naag sures jachh kinnar man mohat |","meaning_en":"he enchants the minds of gods, men, Nagas, Indra, Yakshas and Kinnars.","page":899,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਬਿਬੇਕ ਰਾਜਾ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਕਮਾਨ ਚੜਾਇ ਹੈ।","roman":"Ih chhabi bibek raajaa nripti jidin kamaan charaai hai |","meaning_en":"Of such splendour is King Bibek; on the day he draws his bow,","page":899,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਅਬਿਬੇਕ ਸੁਨਿ ਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਬਾਨ ਚਲਾਇ ਹੈ। ੨੩੧।","roman":"Binu abibek suni ho nripti su aur na baan chalaai hai | 231 |","meaning_en":"listen, O king, none but Abibek will loose an arrow (against him).","page":899,"meaning_status":"draft"}]},{"type":"verse","number":[232],"number_text":"੨੩੨।","page":899,"lines":[{"gurmukhi":"ਅਤਿ ਪ੍ਰਚੰਡ ਅਬਿਕਾਰ ਤੇਜ ਆਖੰਡ ਅਤੁਲ ਬਲ।","roman":"Ati prachand abikaar tej aakhand atul bal |","meaning_en":"Exceedingly fierce, flawless, of unbroken splendour and matchless strength,","page":899,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪ ਅਤਿ ਸੂਰ ਤੂਰ ਬਾਜਤ ਜਿਹ ਜਲ ਥਲ।","roman":"Ati prataap ati soor toor baajat jih jal thal |","meaning_en":"of great glory and great valour, whose trumpets sound over water and land;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਪੇਖਿ ਚਪਲਾ ਚਿਤ ਲਾਜਤ।","roman":"Pavan beg rath chalat pekhi chaplaa chit laajat |","meaning_en":"his chariot runs with the speed of wind, and seeing it lightning feels ashamed;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਤ ਸਬਦ ਚਕ ਚਾਰ ਮੇਘ ਮੋਹਤ ਭ੍ਰਮ ਭਾਜਤ।","roman":"Sunat sabad chak chaar megh mohat bhram bhaajat |","meaning_en":"hearing the sound of its wheels, the clouds are charmed and flee confused;","page":899,"meaning_status":"draft","note":"ਚਕ ਚਾਰ: 'four wheels' or 'astonished'; uncertain."},{"gurmukhi":"ਜਲ ਥਲ ਅਜੇਅ ਅਨਭੈ ਭਟ ਅਤਿ ਉਤਮ ਪਰਵਾਨੀਐ।","roman":"Jal thal ajea anbhai bhat ati utam parvaaneeai |","meaning_en":"unconquerable on water and land, a fearless warrior, held to be most excellent:","page":899,"meaning_status":"draft"},{"gurmukhi":"ਧੀਰਜੁ ਸੁ ਨਾਮ ਜੋਧਾ ਬਿਕਟ ਅਤਿ ਸੁਬਾਹੁ ਜਗ ਮਾਨੀਐ। ੨੩੨।","roman":"Dheerju su naam jodhaa bikat ati subaahu jag maaneeai | 232 |","meaning_en":"Dhiraj (Patience) is the name of this formidable warrior, held in the world to be very strong-armed.","page":899,"meaning_status":"draft","note":"ਸੁਬਾਹੁ: 'strong-armed'; could be a name."}]},{"type":"verse","number":[233],"number_text":"੨੩੩।","page":899,"lines":[{"gurmukhi":"ਧਰਮ ਧੀਰ ਬੀਰ ਜਸਮੀਰ ਅਨਭੀਰ ਬਿਕਟ ਮਤਿ।","roman":"Dharam dheer beer jasmeer anbheer bikat mati |","meaning_en":"Steadfast in dharma, a hero, a chief of glory, fearless, of formidable mind;","page":899,"meaning_status":"draft","note":"ਜਸਮੀਰ: 'chief (mir) of glory'; ਮੀਰ is Persian."},{"gurmukhi":"ਕਲਪ ਬ੍ਰਿਛ ਕੁਬ੍ਰਿਤਨ ਕ੍ਰਿਪਾਨ ਜਸ ਤਿਲਕ ਸੁਭਟ ਅਤਿ।","roman":"Kalap brichh kubritan kripaan jas tilak subhat ati |","meaning_en":"a wish-fulfilling tree (to the good), a sword to the wicked, a great warrior, the crown of glory;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪੁ ਅਤਿ ਓਜ ਅਨਲ ਸਰ ਤੇਜ ਜਰੇ ਰਣ।","roman":"Ati prataapu ati oj anal sar tej jare ran |","meaning_en":"of great glory and vigour, whose fiery arrows burn (foes) in battle;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਹਮ ਅਸਤ੍ਰ ਸਿਵ ਅਸਤ੍ਰ ਨਹਿਨ ਮਾਨਤ ਏਕੈ ਬ੍ਰਣ।","roman":"Braham asatr siv asatr nahin maanat ekai bran |","meaning_en":"he counts Brahma's missile and Shiva's missile as not even a single wound.","page":899,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਦੁਤਿ ਪ੍ਰਕਾਸ ਬ੍ਰਿਤ ਛਤ੍ਰ ਨ੍ਰਿਪ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਜਬ ਛੰਡਿ ਹੈ।","roman":"Ih duti prakaas brit chhatr nrip sasatr asatr jab chhandi hai |","meaning_en":"When this radiant king of good conduct casts his weapons and missiles,","page":899,"meaning_status":"draft","note":"ਬ੍ਰਿਤ ਛਤ੍ਰ: uncertain; perhaps 'king of (Kshatriya) conduct'."},{"gurmukhi":"ਬਿਨੁ ਏਕ ਅਬ੍ਰਿਤ ਸੁਬ੍ਰਿਤ ਨ੍ਰਿਪਤਿ ਅਵਰ ਨ ਆਹਵ ਮੰਡਿ ਹੈ। ੨੩੩।","roman":"Binu ek abrit subrit nripti avar na aahav mandi hai | 233 |","meaning_en":"none but Abrit (Bad Conduct) alone will join battle with King Subrit (Good Conduct).","page":899,"meaning_status":"draft"}]},{"type":"verse","number":[234],"number_text":"੨੩੪।","page":899,"lines":[{"gurmukhi":"ਅਛਿਜ ਗਾਤ ਅਨਭੰਗ ਤੇਜ ਆਖੰਡ ਅਨਿਲ ਬਲ।","roman":"Achhij gaat anbhang tej aakhand anil bal |","meaning_en":"His body cannot be pierced, his splendour unbroken and unending, his strength like the wind;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਕੋ ਪ੍ਰਤਾਪੁ ਜਾਨਤ ਜੀਅ ਜਲ ਥਲ।","roman":"Pavan beg rath ko prataapu jaanat jeea jal thal |","meaning_en":"beings of water and land know the glory of his wind-swift chariot;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਧਨੁਖ ਬਾਨ ਪਰਬੀਨ ਛੀਨ ਸਬ ਅੰਗ ਬ੍ਰਿਤਨ ਕਰਿ।","roman":"Dhanukh baan parbeen chheen sab ang britan kari |","meaning_en":"skilled with bow and arrow, he has weakened his foes in every limb;","page":899,"meaning_status":"draft","note":"ਛੀਨ ਸਬ ਅੰਗ ਬ੍ਰਿਤਨ ਕਰਿ: uncertain."},{"gurmukhi":"ਅਤਿ ਸੁਬਾਹ ਸੰਜਮ ਸੁਬੀਰ ਜਾਨਤ ਨਾਰੀ ਨਰ।","roman":"Ati subaah sanjam subeer jaanat naaree nar |","meaning_en":"very strong-armed is Sanjam (Self-restraint), a fine hero, known to women and men;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਗਹਿ ਧਨੁਖ ਬਾਨ ਪਾਨਹਿ ਧਰਮ ਪਰਮ ਰੂਪ ਧਰਿ ਗਰਜਿ ਹੈ।","roman":"Gahi dhanukh baan paanhi dharam param roop dhari garji hai |","meaning_en":"when, taking bow and arrow in hand and assuming the supreme form of dharma, he roars,","page":899,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਇਕ ਅਬ੍ਰਿਤ ਸੁਬ੍ਰਿਤ ਨ੍ਰਿਪਤਿ ਅਉਰ ਨ ਆਨਿ ਬਰਜਿ ਹੈ। ੨੩੪।","roman":"Binu ik abrit subrit nripti aur na aani barji hai | 234 |","meaning_en":"none but Abrit (Bad Conduct) alone will come to check Subrit (Good Conduct), O king.","page":899,"meaning_status":"draft","note":"Which warrior is meant in verses 233-234 is not fully clear."}]},{"type":"verse","number":[235],"number_text":"੨੩੫।","page":899,"lines":[{"gurmukhi":"ਚਕ੍ਰਿਤ ਚਾਰੁ ਚੰਚਲ ਪ੍ਰਕਾਸ ਬਾਜੀ ਰਥ ਸੋਹਤ।","roman":"Chakrit chaaru chanchal prakaas baajee rath sohat |","meaning_en":"His chariot with wondrous, lovely, restless, shining horses looks splendid;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪ੍ਰਬੀਨ ਧੁਨਿ ਛੀਨ ਬੀਨ ਬਾਜਤ ਮਨ ਮੋਹਤ।","roman":"Ati prabeen dhuni chheen been baajat man mohat |","meaning_en":"most skilled, he plays the vina with subtle sound that enchants the mind;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੇਮ ਰੂਪ ਸੁਭ ਧਰੇ ਨੇਮ ਨਾਮਾ ਭਟ ਭੈ ਕਰ।","roman":"Prem roop subh dhare nem naamaa bhat bhai kar |","meaning_en":"taking a lovely form of love, the warrior named Nem (Discipline) strikes fear;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਪਰਮ ਰੂਪ ਪਰਮੰ ਪ੍ਰਤਾਪ ਜੁਧ ਜੈ ਅਰਿ ਛੈ ਕਰ।","roman":"Param roop parman prataap judh jai ari chhai kar |","meaning_en":"of supreme beauty and supreme glory, victorious in war, destroyer of enemies;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਅਮਿਟ ਬੀਰ ਧੀਰਾ ਬਡੋ ਅਤਿ ਬਲਿਟਿ ਦੁਰ ਧਰਖ ਰਣਿ।","roman":"As amit beer dheeraa bado ati baliti dur dharakh rani |","meaning_en":"such an unfailing hero, steadfast and great, very mighty, invincible in battle;","page":899,"meaning_status":"draft"},{"gurmukhi":"ਅਨਭੈ ਅਭੰਜ ਅਨਮਿਟ ਸੁਧੀਸ ਅਨਬਿਕਾਰ ਅਨਜੈ ਸੁ ਭਣ। ੨੩੫।","roman":"Anbhai abhanj anmit sudhees anbikaar anjai su bhan | 235 |","meaning_en":"fearless, unbreakable, imperishable, wise lord, flawless and unconquerable, so he is called.","page":899,"meaning_status":"draft"}]},{"type":"verse","number":[236],"number_text":"੨੩੬।","page":900,"lines":[{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪ ਅਮਿਤੋਜ ਅਮਿਟ ਅਨਭੈ ਅਭੰਗ ਭਟ।","roman":"Ati prataap amitoj amit anbhai abhang bhat |","meaning_en":"Of great glory and boundless vigour, imperishable, fearless, an unbroken warrior;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਰਥ ਪ੍ਰਮਾਣ ਚਪਲਾ ਸੁ ਚਾਰੁ ਚਮਕਤ ਹੈ ਅਨਕਟ।","roman":"Rath pramaan chaplaa su chaaru chamkat hai ankat |","meaning_en":"his chariot gleams lovely as lightning, unceasingly;","page":900,"meaning_status":"draft","note":"ਅਨਕਟ: uncertain."},{"gurmukhi":"ਨਿਰਖਿ ਸਤ੍ਰੁ ਤਿਹ ਤੇਜ ਚਕ੍ਰਿਤ ਭਯਭੀਤ ਭਜਤ ਰਣਿ।","roman":"Nirkhi satru tih tej chakrit bhaybheet bhajat rani |","meaning_en":"seeing his splendour, enemies are astonished and flee the battle in fear;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਧਰਤ ਧੀਰ ਨਹਿ ਬੀਰ ਤੀਰ ਸਰ ਹੈ ਨਹੀ ਹਠਿ ਰਣਿ।","roman":"Dharat dheer nahi beer teer sar hai nahee hathi rani |","meaning_en":"no hero keeps his nerve, and none stands firm in battle before his arrows;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਬਿਗ੍ਯਾਨ ਨਾਮੁ ਅਨਭੈ ਸੁਭਟ ਅਤਿ ਬਲਿਸਟ ਤਿਹ ਜਾਨੀਐ।","roman":"Bigyaan naamu anbhai subhat ati balisat tih jaaneeai |","meaning_en":"Bigyan (Discriminating Knowledge) is the name of this fearless warrior; know him to be very mighty;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਅਗਿਆਨ ਦੇਸਿ ਜਾ ਕੋ ਸਦਾ ਤ੍ਰਾਸ ਘਰਨ ਘਰਿ ਮਾਨੀਐ। ੨੩੬।","roman":"Agiaan desi jaa ko sadaa traas gharan ghari maaneeai | 236 |","meaning_en":"in the land of Agyan (Ignorance), every house lives in constant dread of him.","page":900,"meaning_status":"draft"}]},{"type":"verse","number":[237],"number_text":"੨੩੭।","page":900,"lines":[{"gurmukhi":"ਬਮਤ ਜ੍ਵਾਲ ਡਮਰੂ ਕਰਾਲ ਡਿਮ ਡਿਮ ਰਣਿ ਬਜਤ।","roman":"Bamat jvaal damroo karaal dim dim rani bajat |","meaning_en":"Spitting flame, his terrible damru drum sounds 'dim dim' in battle;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਘਨ ਪ੍ਰਮਾਨ ਚਕ ਸਬਦ ਘਹਰਿ ਜਾ ਕੋ ਗਲ ਗਜਤ।","roman":"Ghan pramaan chak sabad ghahri jaa ko gal gajat |","meaning_en":"like a cloud, the sound of his wheels rumbles, and his throat thunders;","page":900,"meaning_status":"draft","note":"ਚਕ ਸਬਦ: read as 'sound of wheels'; uncertain."},{"gurmukhi":"ਸਿਮਟਿ ਸਾਂਗ ਸੰਗ੍ਰਹਤ ਸਰਕਿ ਸਾਮੁਹ ਅਰਿ ਝਾਰਤ।","roman":"Simti saang sangrahat sarki saamuh ari jhaarat |","meaning_en":"gathering himself, he grips his lance and, moving forward, strikes down the foes before him;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਿ ਤਾਸੁ ਸੁਰ ਅਸੁਰ ਬ੍ਰਹਮ ਜੈ ਸਬਦ ਉਚਾਰਤ।","roman":"Nirkhi taasu sur asur braham jai sabad uchaarat |","meaning_en":"seeing him, gods, demons and Brahma cry 'Victory!'","page":900,"meaning_status":"draft"},{"gurmukhi":"ਇਸਨਾਨ ਨਾਮ ਅਭਿਮਾਨ ਜੁਤ ਜਿਦਿਨ ਧਨੁਖ ਗਹਿ ਗਰਿਜ ਹੈ।","roman":"Isnaan naam abhimaan jut jidin dhanukh gahi garij hai |","meaning_en":"On the day Isnan (Bathing) by name, full of pride, takes his bow and roars,","page":900,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਇਕ ਕੁਚੀਲ ਸਾਮੁਹਿ ਸਮਰ ਅਉਰ ਨ ਤਾਸੁ ਬਰਜਿ ਹੈ। ੨੩੭।","roman":"Binu ik kucheel saamuhi samar aur na taasu barji hai | 237 |","meaning_en":"none but Kuchil (Filthiness) alone will check him face to face in battle.","page":900,"meaning_status":"draft"}]},{"type":"verse","number":[238],"number_text":"੨੩੮।","page":900,"lines":[{"gurmukhi":"ਇਕਿ ਨਿਬ੍ਰਿਤ ਅਤਿ ਬੀਰ ਦੁਤੀਅ ਭਾਵਨਾ ਮਹਾ ਭਟ।","roman":"Iki nibrit ati beer duteea bhaavnaa mahaa bhat |","meaning_en":"One is Nibrit (Withdrawal), a great hero; the second Bhavna (Devotion), a great warrior;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਅਨਮਿਟ ਅਪਾਰ ਅਨਛਿਜ ਅਨਾਕਟ।","roman":"Ati balisat anmit apaar anchhij anaakat |","meaning_en":"exceedingly mighty, imperishable, boundless, unpierceable and uncut;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰ ਧਾਰਿ ਗਜ ਹੈ ਜਬ ਭੀਰ ਭਾਜਿ ਹੈ ਨਿਰਖਿ ਰਣਿ।","roman":"Sasatr dhaari gaj hai jab bheer bhaaji hai nirkhi rani |","meaning_en":"when they take up weapons and roar, the cowards will see them and flee from the field;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਪਤ੍ਰ ਭੇਸ ਭਹਰਾਤ ਧੀਰ ਧਰ ਹੈ ਨ ਅਨਗਣ।","roman":"Patr bhes bhahraat dheer dhar hai na angan |","meaning_en":"trembling like leaves, the countless (foes) will not keep their nerve.","page":900,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਸੁ ਧੀਰ ਜੋਧਾ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਅਯੋਧਨ ਰਚਿ ਹੈ।","roman":"Ih bidhi su dheer jodhaa nripti jidin ayodhan rachi hai |","meaning_en":"Such are these steadfast warrior kings; on the day they set up battle,","page":900,"meaning_status":"draft"},{"gurmukhi":"ਤਜ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਭਜਿ ਹੈ ਸਕਲ ਏਕ ਨ ਬੀਰ ਬਿਰਚ ਹੈ। ੨੩੮।","roman":"Taj sasatr asatr bhaji hai sakal ek na beer birach hai | 238 |","meaning_en":"all will throw down their weapons and missiles and flee; not one hero will stay.","page":900,"meaning_status":"draft","note":"ਬਿਰਚ ਹੈ: uncertain."}]},{"type":"heading","kind":"chhand","name":"ਸੰਗੀਤ ਛਪਯ ਛੰਦ","gurmukhi":"ਸੰਗੀਤ ਛਪਯ ਛੰਦ","roman":"Sangeet chhapay chhand","meaning_en":"Sangit Chhappay metre.","page":900,"meaning_status":"draft"},{"type":"verse","number":[239],"number_text":"੨੩੯।","page":900,"lines":[{"gurmukhi":"ਤਾਗੜਦੀ ਤੁਰ ਬਾਜ ਹੈ ਜਾਗੜਦੀ ਜੋਧਾ ਜਬ ਜੁਟਹਿ।","roman":"Taagardee tur baaj hai jaagardee jodhaa jab juthi |","meaning_en":"When the horses ... and the warriors clash,","page":900,"meaning_status":"draft","note":"In this metre ਤਾਗੜਦੀ, ਜਾਗੜਦੀ and similar are musical sound-words; left untranslated throughout."},{"gurmukhi":"ਲਾਗੜਦੀ ਲੁਥ ਬਿਥੁਰਹਿ ਸਾਗੜਦੀ ਸੰਨਾਹ ਸੁ ਤੁਟਹਿ।","roman":"Laagardee luth bithurhi saagardee sannaah su tuthi |","meaning_en":"corpses lie scattered and armour is broken;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਭਾਗੜਦੀ ਭੂਤ ਭੈਰੋ ਪ੍ਰਸਿਧ ਅਰੁ ਸਿਧ ਨਿਹਾਰਹਿ।","roman":"Bhaagardee bhoot bhairo prasidh aru sidh nihaarhi |","meaning_en":"ghosts, Bhairav, the famed ones and the Siddhas look on;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਜਾਗੜਦੀ ਜਛ ਜੁਗਣੀ ਜੂਥ ਜੈ ਸਬਦ ਉਚਾਰਹਿ।","roman":"Jaagardee jachh jugnee jooth jai sabad uchaarhi |","meaning_en":"Yakshas and hosts of yoginis cry 'Victory!'","page":900,"meaning_status":"draft"},{"gurmukhi":"ਸੰਸਾਗੜਦੀ ਸੁਭਟ ਸੰਜਮ ਅਮਿਟ ਕਾਗੜਦੀ ਕ੍ਰੁਧ ਜਬ ਗਰਜਿ ਹੈ।","roman":"Sansaagardee subhat sanjam amit kaagardee krudh jab garji hai |","meaning_en":"When the warrior Sanjam (Self-restraint), the unfailing, roars in wrath,","page":900,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਦੰਦਾਗੜਦੀ ਇਕ ਦੁਰਮਤਿ ਬਿਨਾ ਆਗੜਦੀ ਸੁ ਅਉਰ ਨ ਬਰਜਿ ਹੈ। ੨੩੯।","roman":"Dandaagardee ik duramti binaa aagardee su aur na barji hai | 239 |","meaning_en":"none but Durmat (Evil Mind) alone will check him.","page":900,"meaning_status":"draft"}]},{"type":"verse","number":[240],"number_text":"੨੪੦।","page":900,"lines":[{"gurmukhi":"ਜਾਗੜਦੀ ਜੋਗ ਜਯਵਾਨ ਕਾਗੜਦੀ ਕਰਿ ਕ੍ਰੋਧ ਕੜਕਹਿ।","roman":"Jaagardee jog jayvaan kaagardee kari krodh karakhi |","meaning_en":"Jog (Yoga), the victorious, will thunder in anger;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਲਾਗੜਦੀ ਲੁਟ ਅਰੁ ਕੁਟ ਤਾਗੜਦੀ ਤਰਵਾਰ ਸੜਕਹਿ।","roman":"Laagardee lut aru kut taagardee tarvaar sarakhi |","meaning_en":"plundering and pounding, swords will swish;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਸਾਗੜਦੀ ਸਸਤ੍ਰ ਸੰਨਾਹ ਪਾਗੜਦੀ ਪਹਿਰ ਹੈ ਜਵਨ ਦਿਨ।","roman":"Saagardee sasatr sannaah paagardee pahir hai javan din |","meaning_en":"on the day he puts on his weapons and armour,","page":900,"meaning_status":"draft"},{"gurmukhi":"ਸਾਗੜਦੀ ਸਤ੍ਰੁ ਭਜਿ ਹੈ ਟਾਗੜਦੀ ਟਿਕਿ ਹੈ ਨ ਇਕ ਛਿਨ।","roman":"Saagardee satru bhaji hai taagardee tiki hai na ik chhin |","meaning_en":"enemies will flee and not stay even a moment;","page":900,"meaning_status":"draft"},{"gurmukhi":"ਪੰਪਾਗੜਦੀ ਪੀਅਰ ਸਿਤ ਬਰਣ ਮੁਖ ਸਾਗੜਦੀ ਸਮਸਤ ਸਿਧਾਰ ਹੈ।","roman":"Panpaagardee peear sit baran mukh saagardee samsat sidhaar hai |","meaning_en":"their faces turned yellow and white, all will depart,","page":900,"meaning_status":"draft"},{"gurmukhi":"ਅੰਆਗੜਦੀ ਅਮਿਟ ਦੁਰ ਧਰਖ ਭਟ ਜਾਗੜਦੀ ਕਿ ਜਿਦਿਨ ਨਿਹਾਰ ਹੈ। ੨੪੦।","roman":"Anaagardee amit dur dharakh bhat jaagardee ki jidin nihaar hai | 240 |","meaning_en":"on the day the unfailing, invincible warrior looks upon them.","page":900,"meaning_status":"draft"}]},{"type":"verse","number":[241],"number_text":"੨੪੧।","page":901,"lines":[{"gurmukhi":"ਆਗੜਦੀ ਇਕ ਅਰਚਾਰੁ ਪਾਗੜਦੀ ਪੂਜਾ ਜਬ ਕੁਪਹਿ।","roman":"Aagardee ik archaaru paagardee poojaa jab kuphi |","meaning_en":"One is Archa (Worship) and one Puja (Adoration); when they grow angry","page":901,"meaning_status":"draft"},{"gurmukhi":"ਰਾਗੜਦੀ ਰੋਸ ਕਰਿ ਜੋਸ ਪਾਗੜਦੀ ਪਾਇਨ ਜਬ ਰੁਪਹਿ।","roman":"Raagardee ros kari jos paagardee paain jab ruphi |","meaning_en":"and, with fury and zeal, plant their feet firmly,","page":901,"meaning_status":"draft"},{"gurmukhi":"ਸਾਗੜਦੀ ਸਤ੍ਰੁ ਤਜਿ ਅਤ੍ਰ ਭਾਗੜਦੀ ਭਜਹਿ ਸੁ ਭ੍ਰਮਿ ਰਣਿ।","roman":"Saagardee satru taji atr bhaagardee bhajhi su bhrami rani |","meaning_en":"the enemies will abandon their weapons and flee confused from the field,","page":901,"meaning_status":"draft"},{"gurmukhi":"ਆਗੜਦੀ ਐਸ ਉਝੜਹਿ ਪਾਗੜਦੀ ਜਣੁ ਪਵਨ ਪਤ੍ਰ ਬਣ।","roman":"Aagardee ais ujharhi paagardee janu pavan patr ban |","meaning_en":"scattering like the leaves of the forest before the wind;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਸੰਸਾਗੜਦੀ ਸੁਭਟ ਸਬ ਭਜਿ ਹੈ ਤਾਗੜਦੀ ਤੁਰੰਗ ਨਚਾਇ ਹੈ।","roman":"Sansaagardee subhat sab bhaji hai taagardee turang nachaai hai |","meaning_en":"all the warriors will flee, making their horses prance away;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਛੰਛਾਗੜਦੀ ਛਤ੍ਰ ਬ੍ਰਿਤਿ ਛਡਿ ਕੈ ਆਗੜਦੀ ਅਧੋਗਤਿ ਜਾਇ ਹੈ। ੨੪੧।","roman":"Chhanchhaagardee chhatr briti chhadi kai aagardee adhogti jaai hai | 241 |","meaning_en":"abandoning the conduct of Kshatriyas, they will go down to a low state.","page":901,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛਪਯ ਛੰਦ","gurmukhi":"ਛਪਯ ਛੰਦ","roman":"Chhapay chhand","meaning_en":"Chhappay metre.","page":901,"meaning_status":"draft"},{"type":"verse","number":[242],"number_text":"੨੪੨।","page":901,"lines":[{"gurmukhi":"ਚਮਰ ਚਾਰੁ ਚਹੂੰ ਓਰਿ ਢੁਰਤ ਸੁੰਦਰ ਛਬਿ ਪਾਵਤ।","roman":"Chamar chaaru chahoon ori dhurat sundar chhabi paavat |","meaning_en":"Lovely whisks wave on all four sides, giving a beautiful look;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਸੇਤ ਬਸਤ੍ਰ ਅਰੁ ਬਾਜ ਸੇਤ ਸਸਤ੍ਰਣ ਛਬਿ ਛਾਵਤ।","roman":"Set basatr aru baaj set sastran chhabi chhaavat |","meaning_en":"white clothes and white horses, and the beauty of his weapons spreading all around;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪਵਿਤ੍ਰ ਅਬਿਕਾਰ ਅਚਲ ਅਨਖੰਡ ਅਕਟ ਭਟ।","roman":"Ati pavitr abikaar achal ankhand akat bhat |","meaning_en":"utterly pure, flawless, unshakeable, unbroken, an uncut warrior;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਓਜ ਅਨਮਿਟ ਅਨੰਤ ਅਛਲਿ ਰਣਾਕਟ।","roman":"Amit oj anmit anant achhli ranaakat |","meaning_en":"of boundless vigour, imperishable, infinite, undeceivable, a cutter-down in battle;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਧਰ ਅਸਤ੍ਰ ਸਸਤ੍ਰ ਸਾਮੁਹ ਸਮਰ ਜਿਦਿਨ ਨ੍ਰਿਪੋਤਮ ਗਰਜਿ ਹੈ।","roman":"Dhar asatr sasatr saamuh samar jidin nripotam garji hai |","meaning_en":"on the day this best of kings, bearing missiles and weapons, roars face to face in battle,","page":901,"meaning_status":"draft","note":"Probably King Bibek himself; uncertain."},{"gurmukhi":"ਟਿਕਿ ਹੈ ਇਕ ਭਟ ਨਹਿ ਸਮਰਿ ਅਉਰ ਕਵਣ ਤਬ ਬਰਜਿ ਹੈ। ੨੪੨।","roman":"Tiki hai ik bhat nahi samri aur kavan tab barji hai | 242 |","meaning_en":"not one warrior will stand firm in the fight; who else then will check him?","page":901,"meaning_status":"draft"}]},{"type":"verse","number":[243],"number_text":"੨੪੩।","page":901,"lines":[{"gurmukhi":"ਇਕਿ ਬਿਦਿਆ ਅਰੁ ਲਾਜ ਅਮਿਟ ਅਤਿ ਹੀ ਪ੍ਰਤਾਪ ਰਣਿ।","roman":"Iki bidiaa aru laaj amit ati hee prataap rani |","meaning_en":"One is Bidya (Learning), and one Laj (Modesty), imperishable, of great glory in battle;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਭੀਮ ਰੂਪ ਭੈਰੋ ਪ੍ਰਚੰਡ ਅਮਿਟ ਅਦਾਹਣ।","roman":"Bheem roop bhairo prachand amit adaahan |","meaning_en":"of dreadful form like Bhairav, fierce, imperishable, unburnable;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਅਖੰਡ ਅਡੰਡ ਚੰਡ ਪਰਤਾਪ ਰਣਾਚਲ।","roman":"Ati akhand adand chand partaap ranaachal |","meaning_en":"wholly unbroken, beyond punishment, fierce, glorious, unmoving in battle;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਿਖਭ ਕੰਧ ਆਜਾਨ ਬਾਹ ਬਾਨੈਤ ਮਹਾਬਲਿ।","roman":"Brikhabh kandh aajaan baah baanait mahaabli |","meaning_en":"with shoulders like a bull's and arms reaching to the knees, great archers of mighty strength.","page":901,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਅਪਾਰ ਜੋਧਾ ਜੁਗਲ ਜਿਦਿਨ ਨਿਸਾਨ ਬਜਾਇ ਹੈ।","roman":"Ih chhabi apaar jodhaa jugal jidin nisaan bajaai hai |","meaning_en":"On the day these two warriors of boundless splendour sound their drums,","page":901,"meaning_status":"draft"},{"gurmukhi":"ਭਜਿ ਹੈ ਭੂਪ ਤਜਿ ਲਾਜ ਸਭ ਏਕ ਨ ਸਾਮੁਹਿ ਆਇ ਹੈ। ੨੪੩।","roman":"Bhaji hai bhoop taji laaj sabh ek na saamuhi aai hai | 243 |","meaning_en":"the kings will abandon all shame and flee; not one will come before them.","page":901,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਨਰਾਜ ਛੰਦ","roman":"Naraaj chhand","meaning_en":"Naraj metre.","page":901,"meaning_status":"draft"},{"type":"verse","number":[244],"number_text":"੨੪੪।","page":901,"lines":[{"gurmukhi":"ਸੰਜੋਗ ਨਾਮ ਸੂਰਮਾ ਅਖੰਡ ਏਕ ਜਾਨੀਐ।","roman":"Sanjog naam soormaa akhand ek jaaneeai |","meaning_en":"Know one unbroken warrior named Sanjog (Union),","page":901,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਧਾਮਿ ਧਾਮਿ ਜਾਸ ਕੋ ਪ੍ਰਤਾਪ ਆਜ ਮਾਨੀਐ।","roman":"Su dhaami dhaami jaas ko prataap aaj maaneeai |","meaning_en":"whose glory is acknowledged today in house after house;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਡੰਡ ਔ ਅਛੇਦ ਹੈ ਅਭੰਗ ਤਾਸੁ ਭਾਖੀਐ।","roman":"Adand au achhed hai abhang taasu bhaakheeai |","meaning_en":"he is called beyond punishment, unpierceable and unbreakable;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਬਿਚਾਰ ਆਜ ਤਉਨ ਸੋ ਜੁਝਾਰ ਕਉਨ ਰਾਖੀਐ। ੨੪੪।","roman":"Bichaar aaj taun so jujhaar kaun raakheeai | 244 |","meaning_en":"consider today, what warrior can be set against him?","page":901,"meaning_status":"draft"}]},{"type":"verse","number":[245],"number_text":"੨੪੫।","page":901,"lines":[{"gurmukhi":"ਅਖੰਡ ਮੰਡਲੀਕ ਸੋ ਪ੍ਰਚੰਡ ਬੀਰ ਦੇਖੀਐ।","roman":"Akhand mandleek so prachand beer dekheeai |","meaning_en":"See that fierce hero, an unbroken lord of a realm:","page":901,"meaning_status":"draft","note":"ਮੰਡਲੀਕ: ruler of a region."},{"gurmukhi":"ਸੁਕ੍ਰਿਤ ਨਾਮ ਸੂਰਮਾ ਅਜਿਤ ਤਾਸੁ ਲੇਖੀਐ।","roman":"Sukrit naam soormaa ajit taasu lekheeai |","meaning_en":"the warrior named Sukrit (Good Deeds), reckoned unconquerable;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਗਰਜਿ ਸਸਤ੍ਰ ਸਜਿ ਕੈ ਸਲਜਿ ਰਥ ਧਾਇ ਹੈ।","roman":"Garji sasatr saji kai salji rath dhaai hai |","meaning_en":"roaring and armed with weapons, he will charge in his chariot with Salaj (Modesty);","page":901,"meaning_status":"draft","note":"ਸਲਜਿ: read as the warrior Salaj (named at 28.92.3), or 'with modesty'; uncertain."},{"gurmukhi":"ਅਮੰਡ ਮਾਰਤੰਡ ਜ੍ਯੋਂ ਪ੍ਰਚੰਡ ਸੋਭ ਪਾਇ ਹੈ। ੨੪੫।","roman":"Amand maartand jyon prachand sobh paai hai | 245 |","meaning_en":"like the boundless sun, he will shine fiercely.","page":901,"meaning_status":"draft"}]},{"type":"verse","number":[246],"number_text":"੨੪੬।","page":901,"lines":[{"gurmukhi":"ਬਿਸੇਖ ਬਾਣ ਸੈਹਥੀ ਕ੍ਰਿਪਾਨ ਪਾਣਿ ਸਜਿ ਹੈ।","roman":"Bisekh baan saihthee kripaan paani saji hai |","meaning_en":"He will hold special arrows, the saihathi lance and the sword in his hands;","page":901,"meaning_status":"draft","note":"ਸੈਹਥੀ: a kind of lance."},{"gurmukhi":"ਅਮੋਹ ਨਾਮ ਸੂਰਮਾ ਸਰੋਹ ਆਨਿ ਗਜ ਹੈ।","roman":"Amoh naam soormaa saroh aani gaj hai |","meaning_en":"the warrior named Amoh (Non-attachment) will come and thunder in wrath;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਲੋਭ ਨਾਮ ਸੂਰਮਾ ਦੁਤੀਅ ਜੋ ਗਰਜਿ ਹੈ।","roman":"Alobh naam soormaa duteea jo garji hai |","meaning_en":"the second, the warrior named Alobh (Non-greed), who roars,","page":901,"meaning_status":"draft"},{"gurmukhi":"ਰਥੀ ਗਜੀ ਹਈ ਪਤੀ ਅਪਾਰ ਸੈਣ ਭਜਿ ਹੈ। ੨੪੬।","roman":"Rathee gajee haee patee apaar sain bhaji hai | 246 |","meaning_en":"(before them) a boundless army of chariot-riders, elephant-riders, horsemen and foot soldiers will flee.","page":901,"meaning_status":"draft"}]},{"type":"verse","number":[247],"number_text":"੨੪੭।","page":901,"lines":[{"gurmukhi":"ਹਠੀ ਜਪੀ ਤਪੀ ਸਤੀ ਅਖੰਡ ਬੀਰ ਦੇਖੀਐ।","roman":"Hathee japee tapee satee akhand beer dekheeai |","meaning_en":"See an unbroken hero, steadfast, given to japa, austerity and truth;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਚੰਡ ਮਾਰਤੰਡ ਜ੍ਯੋਂ ਅਡੰਡ ਤਾਸੁ ਲੇਖੀਐ।","roman":"Prachand maartand jyon adand taasu lekheeai |","meaning_en":"fierce like the sun, reckon him beyond punishment;","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਜਿਤਿ ਜਉਨ ਜਗਤ ਤੇ ਪਵਿਤ੍ਰ ਅੰਗ ਜਾਨੀਐ।","roman":"Ajiti jaun jagat te pavitr ang jaaneeai |","meaning_en":"know him, pure of limb, as one the world has not conquered:","page":901,"meaning_status":"draft"},{"gurmukhi":"ਅਕਾਮ ਨਾਮ ਸੂਰਮਾ ਭਿਰਾਮ ਤਾਸੁ ਮਾਨੀਐ। ੨੪੭।","roman":"Akaam naam soormaa bhiraam taasu maaneeai | 247 |","meaning_en":"the warrior named Akam (Desirelessness); consider him lovely.","page":901,"meaning_status":"draft"}]},{"type":"verse","number":[248],"number_text":"੨੪੮।","page":902,"lines":[{"gurmukhi":"ਅਕ੍ਰੋਧ ਜੋਧ ਕ੍ਰੋਧ ਕੈ ਬਿਰੋਧ ਸਜਿ ਹੈ ਜਬੈ।","roman":"Akrodh jodh krodh kai birodh saji hai jabai |","meaning_en":"When the warrior Akrodh (Non-anger) takes up the fight in anger,","page":902,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸਾਰਿ ਲਾਜ ਸੂਰਮਾ ਅਪਾਰ ਭਾਜਿ ਹੈ ਸਭੈ।","roman":"Bisaari laaj soormaa apaar bhaaji hai sabhai |","meaning_en":"countless warriors will forget their shame and all flee;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਅਖੰਡ ਦੇਹਿ ਜਾਸ ਕੀ ਪ੍ਰਚੰਡ ਰੂਪ ਜਾਨੀਐ।","roman":"Akhand dehi jaas kee prachand roop jaaneeai |","meaning_en":"his body is unbroken; know his form to be fierce;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਲਜ ਨਾਮ ਸੂਰਮਾ ਸੁ ਮੰਤ੍ਰਿ ਤਾਸੁ ਮਾਨੀਐ। ੨੪੮।","roman":"Su laj naam soormaa su mantri taasu maaneeai | 248 |","meaning_en":"consider the warrior named Laj (Modesty) to be his minister.","page":902,"meaning_status":"draft"}]},{"type":"verse","number":[249],"number_text":"੨੪੯।","page":902,"lines":[{"gurmukhi":"ਸੁ ਪਰਮ ਤਤ ਆਦਿ ਦੈ ਨਿਰਾਹੰਕਾਰ ਗਰਜਿ ਹੈ।","roman":"Su param tat aadi dai niraahankaar garji hai |","meaning_en":"Nirahankar (Humility), with Param Tat (Supreme Essence) and others, will roar;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸੇਖ ਤੋਰ ਸੈਨ ਤੇ ਅਸੇਖ ਬੀਰ ਬਰਜਿ ਹੈ।","roman":"Bisekh tor sain te asekh beer barji hai |","meaning_en":"breaking through the army, he will hold back countless warriors;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸਰੋਖ ਸੈਹਥੀਨ ਲੈ ਅਮੋਘ ਜੋਧ ਜੁਟਿ ਹੈ।","roman":"Sarokh saihtheen lai amogh jodh juti hai |","meaning_en":"taking saihathi lances in fury, the unfailing warriors will clash;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਅਸੇਖ ਬੀਰ ਕਾਰਮਾਦਿ ਕ੍ਰ�ਰ ਕਉਚ ਤੁਟ ਹੈ। ੨੪੯।","roman":"Asekh beer kaarmaadi kra(?)ra kauch tut hai | 249 |","meaning_en":"the bows and armour of countless warriors will be broken.","page":902,"flags":[{"code":"0xad","reason":"unresolved: draws an empty box in the PDF itself: the source font lacks this glyph"}],"meaning_status":"draft","note":"Printed ਕ੍ਰ�ਰ with a damaged character; perhaps ਕ੍ਰੂਰ 'cruel'; left untranslated."}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਨਰਾਜ ਛੰਦ","roman":"Naraaj chhand","meaning_en":"Naraj metre.","page":902,"meaning_status":"draft"},{"type":"verse","number":[250],"number_text":"੨੫੦।","page":902,"lines":[{"gurmukhi":"ਸਭਗਤਿ ਏਕ ਭਾਵਨਾ ਸੁ ਕ੍ਰੋਧ ਸੂਰ ਧਾਇ ਹੈ।","roman":"Sabhagti ek bhaavnaa su krodh soor dhaai hai |","meaning_en":"With devotion, one warrior, Bhavna (Devotion), will charge in anger;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਅਸੇਖ ਮਾਰਤੰਡ ਜ੍ਯੋਂ ਬਿਸੇਖ ਸੋਭ ਪਾਇ ਹੈ।","roman":"Asekh maartand jyon bisekh sobh paai hai |","meaning_en":"like countless suns, he will shine with special splendour;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੰਘਾਰਿ ਸੈਣ ਸਤ੍ਰੂਵੀ ਜੁਝਾਰ ਜੋਧ ਜੁਟਿ ਹੈ।","roman":"Sanghaari sain satroovee jujhaar jodh juti hai |","meaning_en":"slaying the enemy army, the fighting warriors will clash;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਕਰੂਰ ਕੂਰ ਸੂਰਮਾ ਤਰਕ ਤੰਗ ਤੁਟਿ ਹੈ। ੨੫੦।","roman":"Karoor koor soormaa tarak tang tuti hai | 250 |","meaning_en":"the saddle-girths of cruel, fierce warriors will snap.","page":902,"meaning_status":"draft","note":"ਤਰਕ ਤੰਗ ਤੁਟਿ: read as 'girths snapping with a crack'; uncertain."}]},{"type":"verse","number":[251],"number_text":"੨੫੧।","page":902,"lines":[{"gurmukhi":"ਸਿਮਟਿ ਸੂਰ ਸੈਹਥੀ ਸਰਕਿ ਸਾਂਗ ਸੇਲ ਹੈ।","roman":"Simti soor saihthee sarki saang sel hai |","meaning_en":"Gathering, the warriors will thrust saihathis, lances and spears;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਦੁਰੰਤ ਘਾਇ ਝਾਲਿ ਕੈ ਅਨੰਤ ਸੈਣ ਪੇਲਿ ਹੈ।","roman":"Durant ghaai jhaali kai anant sain peli hai |","meaning_en":"bearing terrible wounds, they will drive back the endless army;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਤਮਕਿ ਤੇਗ ਦਾਮਿਣੀ ਸੜਕਿ ਸੂਰ ਮਟਿ ਹੈ।","roman":"Tamki teg daaminee sarki soor mati hai |","meaning_en":"swords will flash like lightning and swish, and the warriors will strike;","page":902,"meaning_status":"draft","note":"ਮਟਿ ਹੈ: uncertain."},{"gurmukhi":"ਨਿਪਟਿ ਕਟਿ ਕੁਟਿ ਕੈ ਅਕਟ ਅੰਗ ਸਟਿ ਹੈ। ੨੫੧।","roman":"Nipti kati kuti kai akat ang sati hai | 251 |","meaning_en":"cutting and pounding thoroughly, they will strike at limbs not yet cut.","page":902,"meaning_status":"draft"}]},{"type":"verse","number":[252],"number_text":"੨੫੨।","page":902,"lines":[{"gurmukhi":"ਨਿਪਟਿ ਸਿੰਘ ਜ੍ਯੋਂ ਪਲਟਿ ਸੂਰ ਸੇਲ ਬਾਹਿ ਹੈ।","roman":"Nipti singh jyon palti soor sel baahi hai |","meaning_en":"Turning back like a lion, the warrior will thrust his spear;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸੇਖ ਬੂਥਨੀਸ ਕੀ ਅਸੇਖ ਸੈਣ ਗਾਹਿ ਹੈ।","roman":"Bisekh boothnees kee asekh sain gaahi hai |","meaning_en":"he will trample the countless army of the great captains;","page":902,"meaning_status":"draft","note":"ਬੂਥਨੀਸ: read as 'lords of troops'; uncertain."},{"gurmukhi":"ਅਰੁਝਿ ਬੀਰ ਅਪ ਮਝਿ ਗਝਿ ਆਨਿ ਜੁਝਿ ਹੈ।","roman":"Arujhi beer ap majhi gajhi aani jujhi hai |","meaning_en":"warriors will come, grapple with one another and fight;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸੇਖ ਦੇਵ ਦਈਤ ਜਛ ਕਿੰਨਰ ਕ੍ਰਿਤ ਬੁਝਿ ਹੈ। ੨੫੨।","roman":"Bisekh dev daeet jachh kinnar krit bujhi hai | 252 |","meaning_en":"gods, demons, Yakshas and Kinnars especially will understand the deed.","page":902,"meaning_status":"draft"}]},{"type":"verse","number":[253],"number_text":"੨੫੩।","page":902,"lines":[{"gurmukhi":"ਸਰਕਿ ਸੇਲ ਸੂਰਮਾ ਮਟਿਕ ਬਾਜ ਸੁਟਿ ਹੈ।","roman":"Sarki sel soormaa matik baaj suti hai |","meaning_en":"Thrusting spears, the warriors will throw riders from prancing horses;","page":902,"meaning_status":"draft","note":"ਮਟਿਕ ਬਾਜ ਸੁਟਿ ਹੈ: uncertain."},{"gurmukhi":"ਅਮੰਡ ਮੰਡਲੀਕ ਸੇ ਅਫੁਟ ਸੂਰ ਫੁਟਿ ਹੈ।","roman":"Amand mandleek se aphut soor phuti hai |","meaning_en":"warriors unbroken, like boundless lords of realms, will be broken.","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਪ੍ਰੇਮ ਨਾਮ ਸੂਰ ਕੋ ਬਿਸੇਖ ਭੂਪ ਜਾਨੀਐ।","roman":"Su prem naam soor ko bisekh bhoop jaaneeai |","meaning_en":"Know the warrior named Prem (Love) as a special king;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਸਾਖ ਤਾਸ ਕੀ ਸਦਾ ਤਿਹੂੰਨ ਲੋਕ ਮਾਨੀਐ। ੨੫੩।","roman":"Su saakh taas kee sadaa tihoonn lok maaneeai | 253 |","meaning_en":"his fame is always acknowledged in the three worlds.","page":902,"meaning_status":"draft"}]},{"type":"verse","number":[254],"number_text":"੨੫੪।","page":902,"lines":[{"gurmukhi":"ਅਨੂਪ ਰੂਪ ਭਾਨ ਸੋ ਅਭੂਤ ਰੂਪ ਮਾਨੀਐ।","roman":"Anoop roop bhaan so abhoot roop maaneeai |","meaning_en":"Of matchless form like the sun, consider his form wondrous;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੰਜੋਗ ਨਾਮ ਸਤ੍ਰੂਹਾ ਸੁ ਬੀਰ ਤਾਸੁ ਜਾਨੀਐ।","roman":"Sanjog naam satroohaa su beer taasu jaaneeai |","meaning_en":"know the warrior Sanjog (Union) as a slayer of enemies;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਸਾਂਤਿ ਨਾਮ ਸੂਰਮਾ ਸੁ ਅਉਰ ਏਕ ਬੋਲੀਐ।","roman":"Su saanti naam soormaa su aur ek boleeai |","meaning_en":"and name one more, the warrior Santi (Peace),","page":902,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਤਾਪ ਜਾਸ ਕੋ ਸਦਾ ਸੁ ਸਰਬ ਲੋਗ ਤੋਲੀਐ। ੨੫੪।","roman":"Prataap jaas ko sadaa su sarab log toleeai | 254 |","meaning_en":"whose glory all people always weigh with esteem.","page":902,"meaning_status":"draft"}]},{"type":"verse","number":[255],"number_text":"੨੫੫।","page":902,"lines":[{"gurmukhi":"ਅਖੰਡ ਮੰਡਲੀਕ ਸੋ ਪ੍ਰਚੰਡ ਰੂਪ ਦੇਖੀਐ।","roman":"Akhand mandleek so prachand roop dekheeai |","meaning_en":"See that unbroken lord of a realm, fierce in form;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਕੋਪ ਸੁਧ ਸਿੰਘ ਕੀ ਸਮਾਨ ਸੂਰ ਪੇਖੀਐ।","roman":"Su kop sudh singh kee samaan soor pekheeai |","meaning_en":"in his wrath, behold the warrior like a true lion;","page":902,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਪਾਠ ਨਾਮ ਤਾਸ ਕੋ ਅਠਾਟ ਤਾਸੁ ਭਾਖੀਐ।","roman":"Su paath naam taas ko athaat taasu bhaakheeai |","meaning_en":"his name is Path (Recitation); call him unshakeable;","page":902,"meaning_status":"draft","note":"ਅਠਾਟ: uncertain; perhaps 'without show' or 'immovable'."},{"gurmukhi":"ਭਜ੍ਯੋ ਨ ਜੁਧ ਤੇ ਕਹੂੰ ਨਿਸੇਸ ਸੂਰ ਸਾਖੀਐ। ੨੫੫।","roman":"Bhajyo na judh te kahoon nises soor saakheeai | 255 |","meaning_en":"he never fled from battle; the moon and the sun are his witnesses.","page":902,"meaning_status":"draft","note":"ਨਿਸੇਸ: 'lord of night', the moon."}]},{"type":"verse","number":[256],"number_text":"੨੫੬।","page":903,"lines":[{"gurmukhi":"ਸੁਕਰਮ ਨਾਮ ਏਕ ਕੋ ਸੁਸਿਛ ਦੂਜ ਜਾਨੀਐ।","roman":"Sukram naam ek ko susichh dooj jaaneeai |","meaning_en":"Know one named Sukaram (Good Action), and the second Susichh (Good Teaching);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਅਭਿਜ ਮੰਡਲੀਕ ਸੋ ਅਛਿਜ ਤੇਜ ਮਾਨੀਐ।","roman":"Abhij mandleek so achhij tej maaneeai |","meaning_en":"consider them unpierceable lords of realms, of imperishable splendour;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਕੋਪ ਸੂਰ ਸਿੰਘ ਜ੍ਯੋਂ ਘਟਾ ਸਮਾਨ ਜੁਟਿ ਹੈ।","roman":"Su kop soor singh jyon ghataa samaan juti hai |","meaning_en":"wrathful like a lion, the warrior will clash like a mass of cloud;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਦੁਰੰਤ ਬਾਜ ਬਾਜਿ ਹੈ ਅਨੰਤ ਸਸਤ੍ਰ ਛੁਟਿ ਹੈ। ੨੫੬।","roman":"Durant baaj baaji hai anant sasatr chhuti hai | 256 |","meaning_en":"terrible instruments will sound, and endless weapons will be loosed.","page":903,"meaning_status":"draft"}]},{"type":"verse","number":[257],"number_text":"੨੫੭।","page":903,"lines":[{"gurmukhi":"ਸੁ ਜਗਿ ਨਾਮ ਏਕ ਕੋ ਪ੍ਰਬੋਧ ਅਉਰ ਮਾਨੀਐ","roman":"Su jagi naam ek ko prabodh aur maaneeai","meaning_en":"One is named Jag (Sacrifice); consider another Prabodh (Awakening);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਦਾਨ ਤੀਸਰਾ ਹਠੀ ਅਖੰਡ ਤਾਸੁ ਜਾਨੀਐ।","roman":"Su daan teesraa hathee akhand taasu jaaneeai |","meaning_en":"the third is Dan (Charity), steadfast; know him unbroken;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਨੇਮ ਨਾਮ ਅਉਰ ਹੈ ਅਖੰਡ ਤਾਸੁ ਭਾਖੀਐ।","roman":"Su nem naam aur hai akhand taasu bhaakheeai |","meaning_en":"another is named Nem (Discipline); call him unbroken,","page":903,"meaning_status":"draft"},{"gurmukhi":"ਜਗਤ ਜਾਸੁ ਜੀਤਿਆ ਜਹਾਨ ਭਾਨੁ ਸਾਖੀਐ। ੨੫੭।","roman":"Jagat jaasu jeetiaa jahaan bhaanu saakheeai | 257 |","meaning_en":"whose glory has conquered the world; the sun of the world is witness.","page":903,"meaning_status":"draft"}]},{"type":"verse","number":[258],"number_text":"੨੫੮।","page":903,"lines":[{"gurmukhi":"ਸੁ ਸਤੁ ਨਾਮ ਏਕ ਕੋ ਸੰਤੋਖ ਅਉਰ ਬੋਲੀਐ।","roman":"Su satu naam ek ko santokh aur boleeai |","meaning_en":"One is named Sat (Truth); name another Santokh (Contentment);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਤਪੁ ਨਾਮ ਤੀਸਰੋ ਦਸੰਤ੍ਰ ਜਾਸੁ ਛੋਲੀਐ।","roman":"Su tapu naam teesro dasantr jaasu chholeeai |","meaning_en":"the third is named Tap (Austerity), whom ... cannot shake;","page":903,"meaning_status":"draft","note":"ਦਸੰਤ੍ਰ ਜਾਸੁ ਛੋਲੀਐ: obscure; uncertain."},{"gurmukhi":"ਸੁ ਜਾਪੁ ਨਾਮ ਏਕ ਕੋ ਪ੍ਰਤਾਪ ਆਜ ਤਾਸ ਕੋ।","roman":"Su jaapu naam ek ko prataap aaj taas ko |","meaning_en":"one is named Jap (Recitation), whose glory is great today,","page":903,"meaning_status":"draft","note":"ਆਜ: 'today' or 'splendour'; uncertain."},{"gurmukhi":"ਅਨੇਕ ਜੁਧ ਜੀਤਿ ਕੈ ਬਰਿਯੋ ਜਿਨੈ ਨਿਰਾਸ ਕੋ। ੨੫੮।","roman":"Anek judh jeeti kai bariyo jinai niraas ko | 258 |","meaning_en":"who, winning many battles, wedded Niras (Freedom from Desire).","page":903,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhappay metre.","page":903,"meaning_status":"draft"},{"type":"verse","number":[259],"number_text":"੨੫੯।","page":903,"lines":[{"gurmukhi":"ਅਤਿ ਪ੍ਰਚੰਡ ਬਲਵੰਡ ਨੇਮ ਨਾਮਾ ਇਕ ਅਤਿ ਭਟ।","roman":"Ati prachand balvand nem naamaa ik ati bhat |","meaning_en":"Exceedingly fierce and mighty is one great warrior named Nem (Discipline);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੇਮ ਨਾਮ ਦੂਸਰੋ ਸੂਰ ਬੀਰਾਰਿ ਰਣੋਤਕਟ।","roman":"Prem naam doosro soor beeraari ranotkat |","meaning_en":"the second warrior is named Prem (Love), a foe of heroes, fearsome in battle;","page":903,"meaning_status":"draft","note":"ਬੀਰਾਰਿ ਰਣੋਤਕਟ: uncertain."},{"gurmukhi":"ਸੰਜਮ ਏਕ ਬਲਿਸਟਿ ਧੀਰ ਨਾਮਾ ਚਤੁਰਥ ਗਨਿ।","roman":"Sanjam ek balisti dheer naamaa chaturath gani |","meaning_en":"one is Sanjam (Self-restraint), very mighty; count the fourth as Dhir (Steadfastness);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਣਯਾਮ ਪੰਚਵੋ ਧਿਆਨ ਨਾਮਾ ਖਸਟਮ ਭਨਿ।","roman":"Praanyaam panchvo dhiaan naamaa khastam bhani |","meaning_en":"the fifth is Pranayam (Breath-control); call the sixth Dhian (Meditation);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਜੋਧਾ ਅਪਾਰ ਅਨਖੰਡ ਸਤਿ ਅਤਿ ਪ੍ਰਤਾਪ ਤਿਹ ਮਾਨੀਐ।","roman":"Jodhaa apaar ankhand sati ati prataap tih maaneeai |","meaning_en":"Sat (Truth) is a boundless, unbroken warrior; consider his glory very great;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰ ਅਸੁਰ ਨਾਗ ਗੰਧ੍ਰਬ ਧਰਮ ਨਾਮਾ ਜਵਨ ਕੋ ਜਾਨੀਐ। ੨੫੯।","roman":"Sur asur naag gandhrab dharam naamaa javan ko jaaneeai | 259 |","meaning_en":"gods, demons, Nagas and Gandharvas know the one named Dharam (Righteousness).","page":903,"meaning_status":"draft"}]},{"type":"verse","number":[260],"number_text":"੨੬੦।","page":903,"lines":[{"gurmukhi":"ਸੁਭਾਚਾਰ ਜਿਹ ਨਾਮ ਸਬਲ ਦੂਸਰ ਅਨੁਮਾਨੋ।","roman":"Subhaachaar jih naam sabal doosar anumaano |","meaning_en":"Consider the second, the mighty one named Subhachar (Good Conduct);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਬਿਕ੍ਰਮ ਤੀਸਰੋ ਸੁਭਟ ਬੁਧਿ ਚਤੁਰਥ ਜੀਅ ਜਾਨੋ।","roman":"Bikram teesro subhat budhi chaturath jeea jaano |","meaning_en":"the third warrior Bikram (Valour); know the fourth to be Budh (Intellect);","page":903,"meaning_status":"draft"},{"gurmukhi":"ਪੰਚਮ ਅਨੁਰਕਤਤਾ ਛਠਮ ਸਾਮਾਧ ਅਭੈ ਭਟ।","roman":"Pancham anurkattaa chhatham saamaadh abhai bhat |","meaning_en":"the fifth Anuraktata (Devotion), the sixth Samadh (Samadhi), a fearless warrior;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਉਦਮ ਅਰੁ ਉਪਕਾਰ ਅਮਿਟ ਅਨਜੀਤ ਅਨਾਕਟ।","roman":"Udam aru upkaar amit anjeet anaakat |","meaning_en":"Udam (Effort) and Upkar (Benevolence), imperishable, unconquered, uncut;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਨਿਰਖਿ ਸਤ੍ਰੁ ਤਜਿ ਆਸਨਨਿ ਬਿਮਨ ਚਿਤ ਭਾਜਤ ਤਵਨ।","roman":"Jih nirkhi satru taji aasanni biman chit bhaajat tavan |","meaning_en":"seeing them, the enemies leave their seats and flee, downcast at heart;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਬਲਿ ਟਾਰਿ ਹਾਰਿ ਆਹਵ ਹਠੀ ਅਠਟ ਠਾਟ ਭੁਲਤ ਗਵਨ। ੨੬੦।","roman":"Bali taari haari aahav hathee athat thaat bhulat gavan | 260 |","meaning_en":"their strength turned aside, the stubborn ones are defeated in battle and lose their way, their array broken.","page":903,"meaning_status":"draft","note":"ਅਠਟ ਠਾਟ ਭੁਲਤ ਗਵਨ: uncertain."}]},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":903,"meaning_status":"draft"},{"type":"verse","number":[261],"number_text":"੨੬੧।","page":903,"lines":[{"gurmukhi":"ਸੁ ਬਿਚਾਰ ਹੈ ਭਟ ਏਕ। ਗੁਨ ਬੀਚ ਜਾਸੁ ਅਨੇਕ।","roman":"Su bichaar hai bhat ek | gun beech jaasu anek |","meaning_en":"One warrior is Bichar (Reflection), in whom there are many virtues;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਸੰਜੋਗ ਹੈ ਇਕ ਅਉਰ। ਜਿਨਿ ਜੀਤਿਆ ਪਤਿ ਗਉਰ। ੨੬੧।","roman":"Sanjog hai ik aur | jini jeetiaa pati gaur | 261 |","meaning_en":"another is Sanjog (Union), who conquered the lord of Gauri (Shiva).","page":903,"meaning_status":"draft","note":"ਪਤਿ ਗਉਰ: read as Shiva, husband of Gauri; uncertain."}]},{"type":"verse","number":[262],"number_text":"੨੬੨।","page":903,"lines":[{"gurmukhi":"ਇਕ ਹੋਮ ਨਾਮ ਸੁ ਬੀਰ। ਅਰਿ ਕੀਨ ਜਾਸੁ ਅਧੀਰ।","roman":"Ik hom naam su beer | ari keen jaasu adheer |","meaning_en":"One hero is named Hom (Fire-offering), who has made his enemies lose heart;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਪੂਜਾ ਸੁ ਅਉਰ ਬਖਾਨ। ਜਿਹ ਸੋ ਨ ਪਉਰਖੁ ਆਨਿ। ੨੬੨।","roman":"Poojaa su aur bakhaan | jih so na paurkhu aani | 262 |","meaning_en":"name another, Puja (Worship), whose valour none other has.","page":903,"meaning_status":"draft"}]},{"type":"verse","number":[263],"number_text":"੨੬੩।","page":903,"lines":[{"gurmukhi":"ਅਨੁਰਕਤਤਾ ਇਕ ਅਉਰ। ਸਭ ਸੁਭਟ ਕੋ ਸਿਰ ਮਉਰ।","roman":"Anurkattaa ik aur | sabh subhat ko sir maur |","meaning_en":"Another is Anuraktata (Devotion), the crown of all warriors;","page":903,"meaning_status":"draft"},{"gurmukhi":"ਬੇਰਕਤਤਾ ਇਕ ਆਨ। ਜਿਹ ਸੋ ਨ ਆਨ ਪ੍ਰਧਾਨ। ੨੬੩।","roman":"Berkattaa ik aan | jih so na aan pradhaan | 263 |","meaning_en":"another is Berakatata (Detachment), than whom none other is foremost.","page":903,"meaning_status":"draft"}]},{"type":"verse","number":[264],"number_text":"੨੬੪।","page":904,"lines":[{"gurmukhi":"ਸਤਸੰਗ ਅਉਰ ਸੁਬਾਹ। ਜਿਹ ਦੇਖ ਜੁਧ ਉਛਾਹ।","roman":"Satsang aur subaah | jih dekh judh uchhaah |","meaning_en":"Another is Satsang (Holy Company), strong-armed, at whose sight zeal for battle arises;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਭਟ ਨੇਹ ਨਾਮ ਅਪਾਰ। ਬਲ ਜਉਨ ਕੋ ਬਿਕਰਾਰ। ੨੬੪।","roman":"Bhat neh naam apaar | bal jaun ko bikraar | 264 |","meaning_en":"a boundless warrior named Neh (Affection), whose strength is formidable.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[265],"number_text":"੨੬੫।","page":904,"lines":[{"gurmukhi":"ਇਕ ਪ੍ਰੀਤਿ ਅਰੁ ਹਰਿ ਭਗਤਿ। ਜਿਹ ਜੋਤਿ ਜਗਮਗ ਜਗਤਿ।","roman":"Ik preeti aru hari bhagti | jih joti jagmag jagti |","meaning_en":"One is Priti (Love), and Hari-bhagati (Devotion to the Lord), whose light glitters through the world;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਭਟ ਦਤ ਮਤ ਮਹਾਨ। ਸਬ ਠਉਰ ਮੈ ਪਰਧਾਨ। ੨੬੫।","roman":"Bhat dat mat mahaan | sab thaur mai pardhaan | 265 |","meaning_en":"the warrior Dutt-mat (the Way of Dutt) is great, foremost in every place.","page":904,"meaning_status":"draft","note":"ਦਤ ਮਤ: read as 'the creed of Dutt'; uncertain."}]},{"type":"verse","number":[266],"number_text":"੨੬੬।","page":904,"lines":[{"gurmukhi":"ਇਕ ਅਕ੍ਰੂਧ ਅਉਰ ਪ੍ਰਬੋਧ। ਰਣ ਦੇਖਿ ਕੈ ਜਿਹ ਕ੍ਰੋਧ।","roman":"Ik akroodh aur prabodh | ran dekhi kai jih krodh |","meaning_en":"One is Akrudh (Non-anger), another Prabodh (Awakening), who grows wrathful on seeing battle;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਭਾਤਿ ਸੈਨ ਬਨਾਇ। ਦੁਹੁ ਦਿਸਿ ਨਿਸਾਨ ਬਜਾਇ। ੨੬੬।","roman":"Ih bhaati sain banaai | duhu disi nisaan bajaai | 266 |","meaning_en":"in this way the armies were arrayed, and drums sounded on both sides.","page":904,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":904,"meaning_status":"draft"},{"type":"verse","number":[267],"number_text":"੨੬੭।","page":904,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਸੈਨ ਬਨਾਇ ਕੈ ਚੜੇ ਨਿਸਾਨ ਬਜਾਇ।","roman":"Ih bidhi sain banaai kai chare nisaan bajaai |","meaning_en":"Arraying their armies in this way, they advanced, beating their drums;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਜਿਹ ਬਿਧਿ ਆਹਵ ਮਚ੍ਯੋ ਸੋ ਸੋ ਕਹਤ ਸੁਨਾਇ। ੨੬੭।","roman":"Jih jih bidhi aahav machyo so so kahat sunaai | 267 |","meaning_en":"in whatever way the battle raged, I tell it all aloud.","page":904,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਰੀ ਭਗਵਤੀ ਛੰਦ","gurmukhi":"ਸ੍ਰੀ ਭਗਵਤੀ ਛੰਦ","roman":"Sree bhagavtee chhand","meaning_en":"Sri Bhagauti metre.","page":904,"meaning_status":"draft"},{"type":"verse","number":[268],"number_text":"੨੬੮।","page":904,"lines":[{"gurmukhi":"ਕਿ ਸੰਬਾਹ ਉਠੇ। ਕਿ ਸਾਵੰਤ ਜੁਟੇ।","roman":"Ki sanbaah uthe | ki saavant jute |","meaning_en":"The armoured ones rose up; the warriors clashed;","page":904,"meaning_status":"draft","note":"ਕਿ at the start of each phrase in this metre is a filler word, left untranslated."},{"gurmukhi":"ਕਿ ਨੀਸਾਣ ਹੁਕੇ। ਕਿ ਬਾਜੰਤ੍ਰ ਧੁਕੇ। ੨੬੮।","roman":"Ki neesaan huke | ki baajantr dhuke | 268 |","meaning_en":"the drums thundered; the instruments boomed.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[269],"number_text":"੨੬੯।","page":904,"lines":[{"gurmukhi":"ਕਿ ਬੰਬਾਲ ਨੇਜੇ। ਕਿ ਜੰਜ੍ਵਾਲ ਤੇਜੇ।","roman":"Ki banbaal neje | ki janjvaal teje |","meaning_en":"Tasselled lances (gleamed); flames blazed;","page":904,"meaning_status":"draft","note":"ਬੰਬਾਲ, ਜੰਜ੍ਵਾਲ: uncertain."},{"gurmukhi":"ਕਿ ਸਾਵੰਤ ਢੂਕੇ। ਕਿ ਹਾ ਹਾਇ ਕੂਕੇ। ੨੬੯।","roman":"Ki saavant dhooke | ki haa haai kooke | 269 |","meaning_en":"the warriors closed in; they cried out 'Alas!'","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[270],"number_text":"੨੭੦।","page":904,"lines":[{"gurmukhi":"ਕਿ ਸਿੰਧੂਰ ਗਜੇ। ਕਿ ਤੰਦੂਰ ਬਜੇ।","roman":"Ki sindhoor gaje | ki tandoor baje |","meaning_en":"Elephants trumpeted; drums sounded;","page":904,"meaning_status":"draft","note":"ਸਿੰਧੂਰ: read as elephants (marked with vermilion); ਤੰਦੂਰ: a drum."},{"gurmukhi":"ਕਿ ਸੰਬਾਹ ਜੁਟੇ। ਕਿ ਸੰਨਾਹ ਫੁਟੇ। ੨੭੦।","roman":"Ki sanbaah jute | ki sannaah phute | 270 |","meaning_en":"the armoured ones clashed; armour burst open.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[271],"number_text":"੨੭੧।","page":904,"lines":[{"gurmukhi":"ਕਿ ਡਾਕੰਤ ਡਉਰੂ। ਕਿ ਭ੍ਰਾਮੰਤ ਭਉਰੂ।","roman":"Ki daakant dauroo | ki bhraamant bhauroo |","meaning_en":"Damru drums rattled; Bhairav roamed about;","page":904,"meaning_status":"draft","note":"ਭਉਰੂ: read as Bhairav; could be 'bees'; uncertain."},{"gurmukhi":"ਕਿ ਆਹਾੜਿ ਡਿਗੇ। ਕਿ ਰਾਕਤ੍ਰ ਭਿਗੇ। ੨੭੧।","roman":"Ki aahaari dige | ki raakatr bhige | 271 |","meaning_en":"they fell in the fray; they were soaked in blood.","page":904,"meaning_status":"draft","note":"Printed ਰਾਕਤ੍ਰ; read as 'blood' (rakat)."}]},{"type":"verse","number":[272],"number_text":"੨੭੨।","page":904,"lines":[{"gurmukhi":"ਕਿ ਚਾਮੁੰਡ ਚਰਮੰ। ਕਿ ਸਾਵੰਤ ਧਰਮੰ।","roman":"Ki chaamund charman | ki saavant dharman |","meaning_en":"Chamunda (with her) shield; the warriors (keeping) their dharma;","page":904,"meaning_status":"draft","note":"ਚਰਮੰ: 'shield of hide'; uncertain."},{"gurmukhi":"ਕਿ ਆਵੰਤ ਜੁਧੰ। ਕਿ ਸਾਨਧ ਬਧੰ। ੨੭੨।","roman":"Ki aavant judhan | ki saanadh badhan | 272 |","meaning_en":"they came into battle; taking aim, they slew.","page":904,"meaning_status":"draft","note":"ਸਾਨਧ ਬਧੰ: uncertain."}]},{"type":"verse","number":[273],"number_text":"੨੭੩।","page":904,"lines":[{"gurmukhi":"ਕਿ ਸਾਵੰਤ ਸਜੇ। ਕਿ ਨੀਸਾਣ ਬਜੇ।","roman":"Ki saavant saje | ki neesaan baje |","meaning_en":"The warriors were armed; the drums sounded;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਜੰਜ੍ਵਾਲ ਕ੍ਰੋਧੰ। ਕਿ ਬਿਸਾਰਿ ਬੋਧੰ। ੨੭੩।","roman":"Ki janjvaal krodhan | ki bisaari bodhan | 273 |","meaning_en":"blazing with anger, forgetting all sense.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[274],"number_text":"੨੭੪।","page":904,"lines":[{"gurmukhi":"ਕਿ ਆਹਾੜ ਮਾਨੀ। ਕਿ ਜ੍ਯੋਂ ਮਛ ਪਾਨੀ।","roman":"Ki aahaar maanee | ki jyon machh paanee |","meaning_en":"At home in the fray, like fish in water,","page":904,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਸਸਤ੍ਰਾਸਤ੍ਰ ਬਾਹੈ। ਕਿ ਜ੍ਯੋਂ ਜੀਤ ਚਾਹੈ। ੨੭੪।","roman":"Ki sastraasatr baahai | ki jyon jeet chaahai | 274 |","meaning_en":"they wield weapons and missiles, as men who long for victory.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[275],"number_text":"੨੭੫।","page":904,"lines":[{"gurmukhi":"ਕਿ ਸਾਵੰਤ ਸੋਹੇ। ਕਿ ਸਾਰੰਗ ਰੋਹੇ।","roman":"Ki saavant sohe | ki saarang rohe |","meaning_en":"The warriors looked splendid; bows were drawn in fury;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਸਸਤ੍ਰਾਸਤ੍ਰ ਬਾਹੇ। ਭਲੇ ਸੈਣ ਗਾਹੇ। ੨੭੫।","roman":"Ki sastraasatr baahe | bhale sain gaahe | 275 |","meaning_en":"they wielded weapons and missiles and churned the army thoroughly.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[276],"number_text":"੨੭੬।","page":904,"lines":[{"gurmukhi":"ਕਿ ਭੈਰਉ ਭਭਕੈ। ਕਿ ਕਾਲੀ ਕੁਹਕੇ।","roman":"Ki bhairau bhabhkai | ki kaalee kuhke |","meaning_en":"Bhairav roared; Kali shrieked;","page":904,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਜੋਗਨ ਜੁਟੀ। ਕਿ ਲੈ ਪਤ੍ਰ ਟੁਟੀ। ੨੭੬।","roman":"Ki jogan jutee | ki lai patr tutee | 276 |","meaning_en":"the yoginis gathered; taking their bowls, they swooped down.","page":904,"meaning_status":"draft"}]},{"type":"verse","number":[277],"number_text":"੨੭੭।","page":905,"lines":[{"gurmukhi":"ਕਿ ਦੇਵੀ ਦਮਕੇ। ਕਿ ਕਾਲੀ ਕੁਹਕੇ।","roman":"Ki devee damke | ki kaalee kuhke |","meaning_en":"The goddess flashed; Kali shrieked;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਭੈਰੋ ਭਕਾਰੈ। ਕਿ ਡਉਰੂ ਡਕਾਰੈ। ੨੭੭।","roman":"Ki bhairo bhakaarai | ki dauroo dakaarai | 277 |","meaning_en":"Bhairav bellowed; the damru rumbled.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[278],"number_text":"੨੭੮।","page":905,"lines":[{"gurmukhi":"ਕਿ ਬਹੁ ਸਸਤ੍ਰ ਬਰਖੇ। ਕਿ ਪਰਮਾਸਤ੍ਰ ਕਰਖੇ।","roman":"Ki bahu sasatr barkhe | ki parmaasatr karkhe |","meaning_en":"Many weapons rained down; supreme missiles were drawn;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਦਈਤਾਸਤ੍ਰ ਛੁਟੇ। ਦੇਵਾਸਤ੍ਰ ਮੁਕੇ। ੨੭੮।","roman":"Ki daeetaasatr chhute | devaasatr muke | 278 |","meaning_en":"demon-missiles were loosed; god-missiles were released.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[279],"number_text":"੨੭੯।","page":905,"lines":[{"gurmukhi":"ਕਿ ਸੈਲਾਸਤ੍ਰ ਸਾਜੇ। ਕਿ ਪਉਨਾਸਤ੍ਰ ਬਾਜੇ।","roman":"Ki sailaasatr saaje | ki paunaasatr baaje |","meaning_en":"Mountain-missiles were readied; wind-missiles struck;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਮੇਘਾਸਤ੍ਰ ਬਰਖੇ। ਕਿ ਅਗਨਾਸਤ੍ਰ ਕਰਖੇ। ੨੭੯।","roman":"Ki meghaasatr barkhe | ki agnaasatr karkhe | 279 |","meaning_en":"cloud-missiles rained; fire-missiles were drawn.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[280],"number_text":"੨੮੦।","page":905,"lines":[{"gurmukhi":"ਕਿ ਹੰਸਾਸਤ੍ਰ ਛੁਟੇ। ਕਿ ਕਾਕਸਤ੍ਰ ਤੁਟੇ।","roman":"Ki hansaasatr chhute | ki kaaksatr tute |","meaning_en":"Swan-missiles were loosed; crow-missiles broke;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਮੇਘਾਸਤ੍ਰ ਬਰਖੇ। ਕਿ ਸੂਕ੍ਰਾਸਤ੍ਰੁ ਕਰਖੇ। ੨੮੦।","roman":"Ki meghaasatr barkhe | ki sookraastru karkhe | 280 |","meaning_en":"cloud-missiles rained; boar-missiles were drawn.","page":905,"meaning_status":"draft","note":"ਸੂਕ੍ਰਾਸਤ੍ਰੁ: 'boar (sukar) missile' or 'Shukra's missile'; uncertain."}]},{"type":"verse","number":[281],"number_text":"੨੮੧।","page":905,"lines":[{"gurmukhi":"ਕਿ ਸਾਵੰਤ੍ਰ ਸਜੇ। ਕਿ ਬ੍ਯੋਮਾਸਤ੍ਰ ਗਜੇ।","roman":"Ki saavantr saje | ki byomaasatr gaje |","meaning_en":"The warriors were armed; sky-missiles thundered;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਜਛਾਸਤ੍ਰ ਛੁਟੇ। ਕਿ ਕਿੰਨ੍ਰਾਸਤ੍ਰ ਮੁਕੇ। ੨੮੧।","roman":"Ki jachhaasatr chhute | ki kinnraasatr muke | 281 |","meaning_en":"Yaksha-missiles were loosed; Kinnar-missiles were released.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[282],"number_text":"੨੮੨।","page":905,"lines":[{"gurmukhi":"ਕਿ ਗੰਧ੍ਰਾਬਸਾਤ੍ਰ ਬਾਹੈ। ਕਿ ਨਰ ਅਸਤ੍ਰ ਗਾਹੈ।","roman":"Ki gandhraabsaatr baahai | ki nar asatr gaahai |","meaning_en":"Gandharva-missiles were wielded; man-missiles churned the ranks;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਚੰਚਾਲ ਨੈਣੰ। ਕਿ ਮੈਮਤ ਬੈਣੰ। ੨੮੨।","roman":"Ki chanchaal nainan | ki maimat bainan | 282 |","meaning_en":"eyes restless; words drunk with rage.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[283],"number_text":"੨੮੩।","page":905,"lines":[{"gurmukhi":"ਕਿ ਆਹਾੜਿ ਡਿਗੈ। ਕਿ ਆਰਕਤ ਭਿਗੈ।","roman":"Ki aahaari digai | ki aarkat bhigai |","meaning_en":"They fell in the fray; they were drenched in blood;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਸਸਤ੍ਰਾਸਤ੍ਰ ਬਜੇ। ਕਿ ਸਾਵੰਤ ਗਜੇ। ੨੮੩।","roman":"Ki sastraasatr baje | ki saavant gaje | 283 |","meaning_en":"weapons and missiles clanged; the warriors thundered.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[284],"number_text":"੨੮੪।","page":905,"lines":[{"gurmukhi":"ਕਿ ਆਵਰਤ ਹੂਰੰ। ਕਿ ਸਾਵਰਤ ਪੂਰੰ।","roman":"Ki aavrat hooran | ki saavrat pooran |","meaning_en":"The houris circled about, choosing husbands in plenty;","page":905,"meaning_status":"draft","note":"ਹੂਰ: Persian 'houri, heavenly maiden'; ਸਾਵਰਤ read as 'choosing husbands' (svayamvar); uncertain."},{"gurmukhi":"ਫਿਰੀ ਐਣ ਗੈਣੰ। ਕਿ ਆਰਕਤ ਨੈਣੰ। ੨੮੪।","roman":"Phiree ain gainan | ki aarkat nainan | 284 |","meaning_en":"they roamed over earth and sky; eyes were red.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[285],"number_text":"੨੮੫।","page":905,"lines":[{"gurmukhi":"ਕਿ ਪਾਵੰਗ ਪੁਲੇ। ਕਿ ਸਰਬਾਸਤ੍ਰ ਖੁਲੇ।","roman":"Ki paavang pule | ki sarbaasatr khule |","meaning_en":"The horses leapt; every missile was let loose;","page":905,"meaning_status":"draft","note":"ਪਾਵੰਗ ਪੁਲੇ: uncertain."},{"gurmukhi":"ਕਿ ਹੰਕਾਰਿ ਬਾਹੈ। ਅਧੰ ਅਧਿ ਲਾਹੈ। ੨੮੫।","roman":"Ki hankaari baahai | adhan adhi laahai | 285 |","meaning_en":"with pride they strike, cutting (foes) in half.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[286],"number_text":"੨੮੬।","page":905,"lines":[{"gurmukhi":"ਛੁਟੀ ਈਸ ਤਾਰੀ। ਕਿ ਸੰਨ੍ਯਾਸ ਧਾਰੀ।","roman":"Chhutee ees taaree | ki sannyaas dhaaree |","meaning_en":"Shiva's trance was broken, he who wears the garb of renunciation;","page":905,"meaning_status":"draft","note":"ਈਸ ਤਾਰੀ: read as 'the Lord's (Shiva's) trance'; uncertain."},{"gurmukhi":"ਕਿ ਗੰਧਰਬ ਗਜੇ। ਕਿ ਬਾਦ੍ਰਿਤ ਬਜੇ। ੨੮੬।","roman":"Ki gandhrab gaje | ki baadrit baje | 286 |","meaning_en":"the Gandharvas thundered; instruments played.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[287],"number_text":"੨੮੭।","page":905,"lines":[{"gurmukhi":"ਕਿ ਪਾਪਾਸਤ੍ਰ ਬਰਖੇ। ਕਿ ਧਰਮਾਸਤ੍ਰ ਕਰਖੇ।","roman":"Ki paapaasatr barkhe | ki dharmaasatr karkhe |","meaning_en":"Sin-missiles rained; dharma-missiles were drawn;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਅਰੋਗਾਸਤ੍ਰ ਛੁਟੇ। ਸੁ ਭੋਗਾਸਤ੍ਰ ਸੁਟੇ। ੨੮੭।","roman":"Arogaasatr chhute | su bhogaasatr sute | 287 |","meaning_en":"health-missiles were loosed; pleasure-missiles were hurled.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[288],"number_text":"੨੮੮।","page":905,"lines":[{"gurmukhi":"ਬਿਬਾਦਾਸਤ੍ਰ ਸਜੇ। ਬਿਰੋਧਾਸਤ੍ਰ ਬਜੇ।","roman":"Bibaadaasatr saje | birodhaasatr baje |","meaning_en":"Dispute-missiles were readied; hostility-missiles struck;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਕੁਮੰਤ੍ਰਾਸਤ੍ਰ ਛੁਟੇ। ਸਮੁੰਤ੍ਰਾਸਤ੍ਰ ਟੁਟੇ। ੨੮੮।","roman":"Kumantraasatr chhute | samuntraasatr tute | 288 |","meaning_en":"evil-counsel missiles were loosed; good-counsel missiles broke.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[289],"number_text":"੨੮੯।","page":905,"lines":[{"gurmukhi":"ਕਿ ਕਾਮਾਸਤ੍ਰ ਛੁਟੇ। ਕਰੋਧਾਸਤ੍ਰ ਤੁਟੇ।","roman":"Ki kaamaasatr chhute | karodhaasatr tute |","meaning_en":"Lust-missiles were loosed; anger-missiles broke;","page":905,"meaning_status":"draft"},{"gurmukhi":"ਬਿਰੋਧਾਸਤ੍ਰ ਬਰਖੇ। ਬਿਮੋਹਾਸਤ੍ਰ ਕਰਖੇ। ੨੮੯।","roman":"Birodhaasatr barkhe | bimohaasatr karkhe | 289 |","meaning_en":"hostility-missiles rained; delusion-missiles were drawn.","page":905,"meaning_status":"draft"}]},{"type":"verse","number":[290],"number_text":"੨੯੦।","page":905,"lines":[{"gurmukhi":"ਚਰਿਤ੍ਰਾਸਤ੍ਰ ਛੁਟੇ। ਕਿ ਮੋਹਾਸਤ੍ਰ ਜੁਟੇ।","roman":"Charitraasatr chhute | ki mohaasatr jute |","meaning_en":"Trickery-missiles were loosed; attachment-missiles clashed;","page":905,"meaning_status":"draft","note":"ਚਰਿਤ੍ਰ: 'wiles, trickery'."},{"gurmukhi":"ਕਿ ਤ੍ਰਾਸਾਸਤ੍ਰ ਬਰਖੇ। ਕਿ ਕ੍ਰੋਧਾਸਤ੍ਰ ਕਰਖੇ। ੨੯੦।","roman":"Ki traasaasatr barkhe | ki krodhaasatr karkhe | 290 |","meaning_en":"terror-missiles rained; wrath-missiles were drawn.","page":905,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ ਛੰਦ","gurmukhi":"ਚੌਪਈ ਛੰਦ","roman":"Chaupaee chhand","meaning_en":"Chaupai.","page":906,"meaning_status":"draft"},{"type":"verse","number":[291],"number_text":"੨੯੧।","page":906,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਬਹੁ ਛੋਰੇ। ਨ੍ਰਿਪ ਬਿਬੇਕ ਕੇ ਭਟ ਝਕਝੋਰੇ।","roman":"Ih bidhi sasatr asatr bahu chhore | nrip bibek ke bhat jhakjhore |","meaning_en":"In this way many weapons and missiles were loosed, and they shook the warriors of King Bibek.","page":906,"meaning_status":"draft"},{"gurmukhi":"ਆਪਨ ਚਲਾ ਨਿਸਰਿ ਤਬ ਰਾਜਾ। ਭਾਤਿ ਭਾਤਿ ਕੇ ਬਾਜਨ ਬਾਜਾ। ੨੯੧।","roman":"Aapan chalaa nisri tab raajaa | bhaati bhaati ke baajan baajaa | 291 |","meaning_en":"Then the king himself came out, and instruments of every kind sounded.","page":906,"meaning_status":"draft","note":"Which king is not stated; probably Abibek."}]},{"type":"verse","number":[292],"number_text":"੨੯੨।","page":906,"lines":[{"gurmukhi":"ਦੁਹੁ ਦਿਸਿ ਪੜਾ ਨਿਸਾਨੈ ਘਾਤਾ। ਮਹਾ ਸਬਦ ਧੁਨਿ ਉਠੀ ਅਘਾਤਾ।","roman":"Duhu disi paraa nisaanai ghaataa | mahaa sabad dhuni uthee aghaataa |","meaning_en":"On both sides the drums were struck, and a great sound arose without ceasing.","page":906,"meaning_status":"draft"},{"gurmukhi":"ਬਰਖਾ ਬਾਣ ਗਗਨ ਗਯੋ ਛਾਈ। ਭੂਤਿ ਪਿਸਾਚ ਰਹੇ ਉਰਝਾਈ। ੨੯੨।","roman":"Barkhaa baan gagan gayo chhaaee | bhooti pisaach rahe urjhaaee | 292 |","meaning_en":"A rain of arrows covered the sky, and ghosts and goblins were caught up in it.","page":906,"meaning_status":"draft"}]},{"type":"verse","number":[293],"number_text":"੨੯੩।","page":906,"lines":[{"gurmukhi":"ਝਿਮਿ ਝਿਮਿ ਸਾਰੁ ਗਗਨ ਤੇ ਬਰਖਾ। ਭਲ ਭਲ ਸੁਭਟ ਪਖਰੀਆ ਪਰਖਾ।","roman":"Jhimi jhimi saaru gagan te barkhaa | bhal bhal subhat pakhreeaa parkhaa |","meaning_en":"Steel rained down from the sky in torrents, and the armoured warriors were well tested.","page":906,"meaning_status":"draft","note":"ਪਖਰੀਆ: warriors with armoured horses."},{"gurmukhi":"ਸਿਮਟੇ ਸੁਭਟ ਅਨੰਤ ਅਪਾਰਾ। ਪਰਿ ਗਈ ਅੰਧ ਧੁੰਧ ਬਿਕਰਾਰਾ। ੨੯੩।","roman":"Simte subhat anant apaaraa | pari gaee andh dhundh bikraaraa | 293 |","meaning_en":"Countless, boundless warriors gathered, and a dreadful blinding dust fell.","page":906,"meaning_status":"draft"}]},{"type":"verse","number":[294],"number_text":"੨੯੪।","page":906,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਬਿਬੇਕ ਤਬ ਰੋਸਹਿ ਭਰਾ। ਸਭ ਸੈਨਾ ਕਹਿ ਆਇਸੁ ਕਰਾ।","roman":"Nrip bibek tab roshi bharaa | sabh sainaa kahi aaisu karaa |","meaning_en":"Then King Bibek was filled with fury and gave orders to his whole army.","page":906,"meaning_status":"draft"},{"gurmukhi":"ਉਮਡੇ ਸੂਰ ਸੁ ਫਉਜ ਬਨਾਈ। ਨਾਮ ਤਾਸ ਕਬਿ ਦੇਤ ਬਤਾਈ। ੨੯੪।","roman":"Umde soor su phauj banaaee | naam taas kabi det bataaee | 294 |","meaning_en":"The warriors surged forward and formed their ranks; the poet tells their names.","page":906,"meaning_status":"draft"}]},{"type":"verse","number":[295],"number_text":"੨੯੫।","page":906,"lines":[{"gurmukhi":"ਸਿਰੀ ਪਾਖਰੀ ਟੋਪ ਸਵਾਰੇ। ਚਿਲਤਹ ਰਾਗ ਸੰਜੋਵਾ ਡਾਰੇ।","roman":"Siree paakhree top savaare | chiltah raag sanjovaa daare |","meaning_en":"They put on head-armour, horse-armour and helmets, and donned quilted coats and mail;","page":906,"meaning_status":"draft","note":"ਚਿਲਤਹ: chilta, quilted armour; ਰਾਗ: uncertain."},{"gurmukhi":"ਚਲੇ ਜੁਧ ਕੇ ਕਾਜ ਸੁ ਬੀਰਾ। ਸੂਖਤ ਭਯੋ ਨਦਨ ਕੋ ਨੀਰਾ। ੨੯੫।","roman":"Chale judh ke kaaj su beeraa | sookhat bhayo nadan ko neeraa | 295 |","meaning_en":"the heroes set out for war, and the water of the rivers dried up.","page":906,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":906,"meaning_status":"draft"},{"type":"verse","number":[296],"number_text":"੨੯੬।","page":906,"lines":[{"gurmukhi":"ਦੁਹੂ ਦਿਸਨ ਮਾਰੂ ਬਜ੍ਯੋ ਪਰ੍ਯੋ ਨਿਸਾਣੇ ਘਾਉ।","roman":"Duhoo disan maaroo bajyo paryo nisaane ghaau |","meaning_en":"On both sides the Maru war-music sounded and the drums were struck;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਉਮਡਿ ਦੁਬਹੀਆ ਉਠਿ ਚਲੇ ਭਯੋ ਭਿਰਨ ਕੋ ਚਾਉ। ੨੯੬।","roman":"Umdi dubheeaa uthi chale bhayo bhiran ko chaau | 296 |","meaning_en":"the warriors surged up on both sides and moved forward, eager to fight.","page":906,"meaning_status":"draft","note":"ਦੁਬਹੀਆ: read as 'those of both sides' or 'warriors fighting with both arms'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":906,"meaning_status":"draft"},{"type":"verse","number":[297],"number_text":"੨੯੭।","page":906,"lines":[{"gurmukhi":"ਰਣੰ ਸੁਧਿ ਸਾਵੰਤ ਭਾਵੰਤ ਗਾਜੇ।","roman":"Ranan sudhi saavant bhaavant gaaje |","meaning_en":"In the battle, the warriors, mindful of the fight, roared with zeal;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਤਹਾ ਤੂਰ ਭੇਰੀ ਮਹਾ ਸੰਖ ਬਾਜੇ।","roman":"Tahaa toor bheree mahaa sankh baaje |","meaning_en":"there trumpets, kettledrums and great conches sounded;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਭਯੋ ਉਚ ਕੋਲਾਹਲੰ ਬੀਰ ਖੇਤੰ।","roman":"Bhayo uch kolaahlan beer khetan |","meaning_en":"a loud tumult rose on the field of heroes;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਬਹੇ ਸਸਤ੍ਰ ਅਸਤ੍ਰੰ ਨਚੇ ਭੂਤ ਪ੍ਰੇਤੰ। ੨੯੭।","roman":"Bahe sasatr astran nache bhoot pretan | 297 |","meaning_en":"weapons and missiles were wielded, and ghosts and spirits danced.","page":906,"meaning_status":"draft"}]},{"type":"verse","number":[298],"number_text":"੨੯੮।","page":906,"lines":[{"gurmukhi":"ਫਰੀ ਧੋਪ ਪਾਇਕ ਸੁ ਖੰਡੇ ਬਿਸੇਖੰ।","roman":"Pharee dhop paaik su khande bisekhan |","meaning_en":"Shields, swords, foot soldiers and fine double-edged swords;","page":906,"meaning_status":"draft","note":"ਧੋਪ: a kind of sword; ਖੰਡੇ: double-edged swords."},{"gurmukhi":"ਤੁਰੇ ਤੁੰਦ ਤਾਜੀ ਭਏ ਭੂਤ ਭੇਖੰ।","roman":"Ture tund taajee bhae bhoot bhekhan |","meaning_en":"swift Arab horses moved, (their riders) looking like ghosts;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਰਣੰ ਰਾਗ ਬਜੇ ਤਿ ਗਜੇ ਭਟਾਣੰ।","roman":"Ranan raag baje ti gaje bhataanan |","meaning_en":"battle music sounded and the warriors thundered;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰੀ ਤਤ ਨਚੇ ਪਲਟੇ ਭਟਾਣੰ। ੨੯੮।","roman":"Turee tat nache palte bhataanan | 298 |","meaning_en":"the horses danced in rhythm and the warriors wheeled about.","page":906,"meaning_status":"draft"}]},{"type":"verse","number":[299],"number_text":"੨੯੯।","page":906,"lines":[{"gurmukhi":"ਹਿਣੰਕੇਤ ਹੈਵਾਰ ਗੈਵਾਰ ਗਾਜੀ।","roman":"Hinanket haivaar gaivaar gaajee |","meaning_en":"Horses neighed; elephants and warriors roared;","page":906,"meaning_status":"draft","note":"ਗਾਜੀ: Persian/Arabic 'ghazi, warrior'."},{"gurmukhi":"ਮਟਕੇ ਮਹਾਬੀਰ ਸੁਟੇ ਸਿਰਾਜੀ।","roman":"Matke mahaabeer sute siraajee |","meaning_en":"great heroes strutted, and Shirazi horses were thrown down;","page":906,"meaning_status":"draft","note":"ਸੁਟੇ ਸਿਰਾਜੀ: uncertain; perhaps horses from Shiraz."},{"gurmukhi":"ਕੜਾਕੁਟ ਸਸਤ੍ਰਾਸਤ੍ਰ ਬਜੇ ਅਪਾਰੰ।","roman":"Karaakut sastraasatr baje apaaran |","meaning_en":"weapons and missiles clashed without end with a crash;","page":906,"meaning_status":"draft"},{"gurmukhi":"ਨਚੇ ਸੁਧ ਸਿਧੰ ਉਠੀ ਸਸਤ੍ਰ ਝਾਰੰ। ੨੯੯।","roman":"Nache sudh sidhan uthee sasatr jhaaran | 299 |","meaning_en":"the pure Siddhas danced, and sparks flew from the weapons.","page":906,"meaning_status":"draft"}]},{"type":"verse","number":[300],"number_text":"੩੦੦।","page":907,"lines":[{"gurmukhi":"ਕਿਲੰਕੀਤ ਕਾਲੀ ਕਮਛ੍ਯਾ ਕਰਾਲੰ।","roman":"Kilankeet kaalee kamchhyaa karaalan |","meaning_en":"Terrible Kali and Kamakhya shrieked;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਬਕ੍ਯੋ ਬੀਰ ਬੈਤਾਲੰ ਬਾਮੰਤ ਜ੍ਵਾਲੰ।","roman":"Bakyo beer baitaalan baamant jvaalan |","meaning_en":"the heroic Baital babbled, spitting flames;","page":907,"meaning_status":"draft","note":"ਬੈਤਾਲ: a vampire-spirit (vetal)."},{"gurmukhi":"ਚਵੀ ਚਾਂਵਡੀ ਚਾਵ ਚਉਸਠਿ ਬਾਲੰ।","roman":"Chavee chaanvdee chaav chausthi baalan |","meaning_en":"Chamunda cried out eagerly, with the sixty-four maidens;","page":907,"meaning_status":"draft","note":"The sixty-four yoginis."},{"gurmukhi":"ਕਰੈ ਸ੍ਰੋਣਹਾਰੰ ਬਮੈ ਜੋਗ ਜ੍ਵਾਲੰ। ੩੦੦।","roman":"Karai sronhaaran bamai jog jvaalan | 300 |","meaning_en":"they take up blood, and the yoginis spit flames.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[301],"number_text":"੩੦੧।","page":907,"lines":[{"gurmukhi":"ਛੁਰੀ ਛਿਪ੍ਰ ਛੰਡੈਤਿ ਮੰਡੈ ਰਣਾਰੰ।","roman":"Chhuree chhipr chhandaiti mandai ranaaran |","meaning_en":"Daggers are swiftly hurled, and the battlefield is set;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਤਮਕੈਤ ਤਾਜੀ ਭਭਕੈ ਭਟਾਣੰ।","roman":"Tamkait taajee bhabhkai bhataanan |","meaning_en":"Arab horses grow fiery, and the warriors bellow;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਸੁਭੇ ਸੰਦਲੀ ਬੋਜ ਬਾਜੀ ਅਪਾਰੰ।","roman":"Subhe sandlee boj baajee apaaran |","meaning_en":"countless sandal-coloured and bay horses look splendid;","page":907,"meaning_status":"draft","note":"ਬੋਜ: read as a horse colour; uncertain."},{"gurmukhi":"ਬਹੇ ਬੋਰ ਪਿੰਗੀ ਸਮੁਦੇ ਕੰਧਾਰੰ। ੩੦੧।","roman":"Bahe bor pingee samude kandhaaran | 301 |","meaning_en":"chestnut, tawny, dun and Kandahari horses run.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[302],"number_text":"੩੦੨।","page":907,"lines":[{"gurmukhi":"ਤੁਰੇ ਤੁੰਦ ਤਾਜੀ ਉਠੇ ਕਛ ਅਛੰ।","roman":"Ture tund taajee uthe kachh achhan |","meaning_en":"Swift Arab horses moved, and fine Kachhi horses rose up;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਕਛੇ ਆਰਬੀ ਪਬ ਮਾਨੋ ਸਪਛੰ।","roman":"Kachhe aarbee pab maano sapchhan |","meaning_en":"Kachhi and Arabian horses, like winged mountains;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਉਠੀ ਧੂਰਿ ਪੂਰੰ ਛੁਹੀ ਐਣ ਗੈਣੰ।","roman":"Uthee dhoori pooran chhuhee ain gainan |","meaning_en":"the dust rose in masses, touching earth and sky;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਭਯੋ ਅੰਧ ਧੁੰਧੰ ਪਰੀ ਜਾਨੁ ਰੈਣੰ। ੩੦੨।","roman":"Bhayo andh dhundhan paree jaanu rainan | 302 |","meaning_en":"it became pitch dark, as though night had fallen.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[303],"number_text":"੩੦੩।","page":907,"lines":[{"gurmukhi":"ਇਤੈ ਦਤ ਧਾਯੋ ਅਨਾਦਤ ਉਤੰ।","roman":"Itai dat dhaayo anaadat utan |","meaning_en":"On this side Dutt charged, on that side Anadat;","page":907,"meaning_status":"draft","note":"ਦਤ / ਅਨਾਦਤ: read as the warrior Dutt (Dutt-mat, 28.44.1) and his opposite; perhaps 'Giving' and 'Not-giving'; uncertain."},{"gurmukhi":"ਰਹੀ ਧੂਰਿ ਪੂਰੰ ਪਰੀ ਕਟਿ ਲੁਥੰ।","roman":"Rahee dhoori pooran paree kati luthan |","meaning_en":"the dust filled the air, and cut-down corpses lay about;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਅਨਾਵਰਤ ਬੀਰੰ ਮਹਾਬਰਤ ਧਾਰੀ।","roman":"Anaavrat beeran mahaabrat dhaaree |","meaning_en":"Anabrat (Vowlessness) the warrior, and the bearer of great vows,","page":907,"meaning_status":"draft","note":"ਅਨਾਵਰਤ: uncertain."},{"gurmukhi":"ਚੜ੍ਯੋ ਚਉਪਿ ਕੈ ਤੁੰਦ ਨਚੇ ਤਤਾਰੀ। ੩੦੩।","roman":"Charyo chaupi kai tund nache tataaree | 303 |","meaning_en":"rode out eagerly, their swift Tatar horses dancing.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[304],"number_text":"੩੦੪।","page":907,"lines":[{"gurmukhi":"ਖੁਰੰ ਖੇਹ ਉਠੀ ਛਯੋ ਰਥ ਭਾਨੰ।","roman":"Khuran kheh uthee chhayo rath bhaanan |","meaning_en":"Dust rose from the hooves and covered the chariot of the sun;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਦਿਸਾ ਬੇਦਿਸਾ ਭੂ ਨ ਦਿਖ੍ਯਾ ਸਮਾਨੰ।","roman":"Disaa bedisaa bhoo na dikhyaa samaanan |","meaning_en":"the directions, the spaces between them and the earth all looked alike;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਛੁਟੇ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਪਰੀ ਭੀਰ ਭਾਰੀ।","roman":"Chhute sasatr asatr paree bheer bhaaree |","meaning_en":"weapons and missiles were loosed, and a heavy press of battle fell;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਛੁਟੇ ਤੀਰ ਕਰਵਾਰ ਕਾਤੀ ਕਟਾਰੀ। ੩੦੪।","roman":"Chhute teer karvaar kaatee kataaree | 304 |","meaning_en":"arrows, swords, knives and daggers were let fly.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[305],"number_text":"੩੦੫।","page":907,"lines":[{"gurmukhi":"ਗਹੇ ਬਾਣ ਦਤੰ ਅਨਾਦਤ ਮਾਰ੍ਯੋ।","roman":"Gahe baan datan anaadat maaryo |","meaning_en":"Dutt took up his arrows and struck Anadat;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਭਜੀ ਸਰਬ ਸੈਣੰ ਨ ਨੈਣੰ ਨਿਹਾਰ੍ਯੋ।","roman":"Bhajee sarab sainan na nainan nihaaryo |","meaning_en":"his whole army fled without looking back;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ੍ਯੋ ਬੀਰ ਏਕੈ ਅਨੇਕੰ ਪਰਾਨੋ।","roman":"Jinyo beer ekai anekan paraano |","meaning_en":"a single hero conquered, and many fled,","page":907,"meaning_status":"draft"},{"gurmukhi":"ਪੁਰਾਨੇ ਪਲਾਸੀ ਹਨੇ ਪੌਨ ਮਾਨੋ। ੩੦੫।","roman":"Puraane palaasee hane paun maano | 305 |","meaning_en":"like old palas leaves struck by the wind.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[306],"number_text":"੩੦੬।","page":907,"lines":[{"gurmukhi":"ਰਣੰ ਰੋਸ ਕੈ ਲੋਭ ਬਾਜੀ ਮਟਕ੍ਯੋ।","roman":"Ranan ros kai lobh baajee matkyo |","meaning_en":"In the battle, Lobh (Greed) spurred his horse in fury;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਭਜ੍ਯੋ ਬੀਰ ਬਾਚ੍ਯੋ ਅਰ੍ਯੋ ਸੁ ਝਟਕ੍ਯੋ।","roman":"Bhajyo beer baachyo aryo su jhatkyo |","meaning_en":"the warrior who fled was spared; he who stood his ground was cut down;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਫਿਰ੍ਯੋ ਦੇਖ ਬੀਰੰ ਅਨਾਲੋਭ ਧਾਯੋ।","roman":"Phiryo dekh beeran anaalobh dhaayo |","meaning_en":"seeing the warrior turn, Analobh (Non-greed) charged;","page":907,"meaning_status":"draft"},{"gurmukhi":"ਛੁਟੇ ਬਾਣ ਐਸੇ ਸਬੈ ਬ੍ਯੋਮ ਛਾਯੋ। ੩੦੬।","roman":"Chhute baan aise sabai byom chhaayo | 306 |","meaning_en":"such arrows were loosed that the whole sky was covered.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[307],"number_text":"੩੦੭।","page":907,"lines":[{"gurmukhi":"ਦਸੰ ਬਾਣ ਲੈ ਬੀਰ ਧੀਰੰ ਪ੍ਰਹਾਰੇ।","roman":"Dasan baan lai beer dheeran prahaare |","meaning_en":"Taking ten arrows, the warrior (Lobh) struck Dhiraj (Patience);","page":907,"meaning_status":"draft","note":"Subject inferred as Lobh; uncertain."},{"gurmukhi":"ਸਰੰ ਸਠਿ ਲੈ ਸੰਜਮੈ ਤਾਕਿ ਮਾਰੇ।","roman":"Saran sathi lai sanjmai taaki maare |","meaning_en":"taking sixty arrows, he aimed and struck Sanjam (Self-restraint);","page":907,"meaning_status":"draft"},{"gurmukhi":"ਨਵੰ ਬਾਣ ਸੋ ਨੇਮ ਕੋ ਅੰਗ ਛੇਦ੍ਯੋ।","roman":"Navan baan so nem ko ang chhedyo |","meaning_en":"with nine arrows he pierced the body of Nem (Discipline);","page":907,"meaning_status":"draft"},{"gurmukhi":"ਬਲੀ ਬੀਸਿ ਬਾਣਾਨਿ ਬਿਗ੍ਯਾਨ ਬੇਧ੍ਯੋ। ੩੦੭।","roman":"Balee beesi baanaani bigyaan bedhyo | 307 |","meaning_en":"the mighty one pierced Bigyan (Knowledge) with twenty arrows.","page":907,"meaning_status":"draft"}]},{"type":"verse","number":[308],"number_text":"੩੦੮।","page":908,"lines":[{"gurmukhi":"ਪਚਿਸ ਬਾਣ ਪਾਵਿਤ੍ਰਤਾ ਕੋ ਪ੍ਰਹਾਰੇ।","roman":"Pachis baan paavitrataa ko prahaare |","meaning_en":"He struck Pavitrata (Purity) with twenty-five arrows;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਅਸੀਹ ਬਾਣ ਅਰਚਾਹਿ ਕੈ ਅੰਗਿ ਝਾਰੇ।","roman":"Aseeh baan archaahi kai angi jhaare |","meaning_en":"he shot eighty arrows into the body of Archa (Worship);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਪਚਾਸੀ ਸਰੰ ਪੂਰਿ ਪੂਜਾਹਿ ਛੇਦ੍ਯੋ।","roman":"Pachaasee saran poori poojaahi chhedyo |","meaning_en":"with a full eighty-five arrows he pierced Puja (Adoration);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਬਡੋ ਲਸਟਕਾ ਲੈ ਸਲਜਾਹਿ ਭੇਦ੍ਯੋ। ੩੦੮।","roman":"Bado lasatkaa lai saljaahi bhedyo | 308 |","meaning_en":"taking a great cudgel, he struck Salaj (Modesty).","page":908,"meaning_status":"draft","note":"ਲਸਟਕਾ: 'staff, cudgel'."}]},{"type":"verse","number":[309],"number_text":"੩੦੯।","page":908,"lines":[{"gurmukhi":"ਬਿਆਸੀ ਬਲੀ ਬਾਣ ਬਿਦ੍ਯਾਹਿ ਮਾਰੇ।","roman":"Biaasee balee baan bidyaahi maare |","meaning_en":"The mighty one struck Bidya (Learning) with eighty-two arrows;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਤਪਸ੍ਯਾਹਿ ਪੈ ਤਾਕਿ ਤੇਤੀਸ ਡਾਰੇ।","roman":"Tapsyaahi pai taaki tetees daare |","meaning_en":"aiming at Tapasya (Austerity), he shot thirty-three;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਕਈ ਬਾਣ ਸੋ ਕੀਰਤਨੰ ਅੰਗ ਛੇਦ੍ਯੋ।","roman":"Kaee baan so keeratnan ang chhedyo |","meaning_en":"with several arrows he pierced the body of Kirtan (Praise);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਅਲੋਭਾਦਿ ਜੋਧਾ ਭਲੀ ਭਾਤਿ ਭੇਦ੍ਯੋ। ੩੦੯।","roman":"Alobhaadi jodhaa bhalee bhaati bhedyo | 309 |","meaning_en":"he thoroughly pierced Alobh (Non-greed) and the other warriors.","page":908,"meaning_status":"draft"}]},{"type":"verse","number":[310],"number_text":"੩੧੦।","page":908,"lines":[{"gurmukhi":"ਨ੍ਰਿਹੰਕਾਰ ਕੋ ਬਾਨ ਅਸੀਨ ਛੇਦ੍ਯੋ।","roman":"Nrihankaar ko baan aseen chhedyo |","meaning_en":"He pierced Nirahankar (Humility) with eighty arrows;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਭਲੇ ਪਰਮ ਤਤ੍ਵਾਦਿ ਕੋ ਬਛ ਭੇਦ੍ਯੋ।","roman":"Bhale param tatvaadi ko bachh bhedyo |","meaning_en":"he pierced the chests of Param Tat (Supreme Essence) and the others;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਕਈ ਬਾਣ ਕਰੁਣਾਹਿ ਕੇ ਅੰਗਿ ਝਾਰੇ।","roman":"Kaee baan karunaahi ke angi jhaare |","meaning_en":"he shot several arrows into the body of Karuna (Compassion);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਸਰੰ ਸਉਕ ਸਿਛ੍ਆ ਕੇ ਅੰਗਿ ਮਾਰੇ। ੩੧੦।","roman":"Saran sauk sichha'aa ke angi maare | 310 |","meaning_en":"he struck a hundred arrows into the body of Sichha (Teaching).","page":908,"meaning_status":"draft","note":"ਸਉਕ: read as 'a hundred'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":908,"meaning_status":"draft"},{"type":"verse","number":[311],"number_text":"੩੧੧।","page":908,"lines":[{"gurmukhi":"ਦਾਨ ਆਨਿ ਪੁਜਿਯੋ ਤਬੈ ਗ੍ਯਾਨ ਬਾਨ ਲੈ ਹਾਥਿ।","roman":"Daan aani pujiyo tabai gyaan baan lai haathi |","meaning_en":"Then Dan (Charity) arrived, holding the arrow of Gyan (Knowledge) in his hand;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਜੁਆਨ ਜਾਨਿ ਮਾਰ੍ਯੋ ਤਿਸੈ ਧ੍ਯਾਨ ਮੰਤ੍ਰ ਕੇ ਸਾਥ। ੩੧੧।","roman":"Juaan jaani maaryo tisai dhyaan mantr ke saath | 311 |","meaning_en":"knowing him a worthy foe, he struck him with the mantra of Dhian (Meditation).","page":908,"meaning_status":"draft","note":"ਜੁਆਨ ਜਾਨਿ: lit. 'knowing (him) a young warrior'; whom he struck is implied (Lobh); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":908,"meaning_status":"draft"},{"type":"verse","number":[312],"number_text":"੩੧੨।","page":908,"lines":[{"gurmukhi":"ਰਣੰ ਉਛਲ੍ਯੋ ਦਾਨ ਜੋਧਾ ਮਹਾਨੰ।","roman":"Ranan uchhlyo daan jodhaa mahaanan |","meaning_en":"In the battle the great warrior Dan (Charity) leapt forward,","page":908,"meaning_status":"draft"},{"gurmukhi":"ਸਭੈ ਸਸਤ੍ਰ ਬੇਤਾ ਅਤਿ ਅਸਤ੍ਰੰ ਨਿਧਾਨੰ।","roman":"Sabhai sasatr betaa ati astran nidhaanan |","meaning_en":"knower of all weapons, a treasury of missiles;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਦਸੰ ਬਾਣ ਸੋ ਲੋਭ ਕੋ ਬਛਿ ਮਾਰ੍ਯੋ।","roman":"Dasan baan so lobh ko bachhi maaryo |","meaning_en":"with ten arrows he struck Lobh (Greed) in the chest;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਸਰੰ ਸਪਤ ਸੋ ਕ੍ਰੋਧ ਕੋ ਦੇਹੁ ਤਾਰ੍ਯੋ। ੩੧੨।","roman":"Saran sapat so krodh ko dehu taaryo | 312 |","meaning_en":"with seven arrows he pierced through the body of Krodh (Anger).","page":908,"meaning_status":"draft","note":"ਦੇਹੁ ਤਾਰ੍ਯੋ: uncertain."}]},{"type":"verse","number":[313],"number_text":"੩੧੩।","page":908,"lines":[{"gurmukhi":"ਨਵੰ ਬਾਣ ਬੇਧ੍ਯੋ ਅਨੰਨ੍ਯਾਸ ਬੀਰੰ।","roman":"Navan baan bedhyo anannyaas beeran |","meaning_en":"With nine arrows he pierced the warrior Anannyas,","page":908,"meaning_status":"draft","note":"ਅਨੰਨ੍ਯਾਸ: name obscure, perhaps 'Non-renunciation'; uncertain."},{"gurmukhi":"ਤ੍ਰਿਯੋ ਤੀਰ ਭੇਦ੍ਯੋ ਅਨਾਬਰਤ ਧੀਰੰ।","roman":"Triyo teer bhedyo anaabrat dheeran |","meaning_en":"with three arrows he pierced the steadfast Anabrat (Vowlessness);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਭਯੋ ਭੇਦਿ ਕ੍ਰੋਧੰ ਸਤੰ ਸੰਗਿ ਮਾਰੇ।","roman":"Bhayo bhedi krodhan satan sangi maare |","meaning_en":"Krodh (Anger) was pierced, and a hundred others were slain along with him;","page":908,"meaning_status":"draft","note":"ਸਤੰ ਸੰਗਿ ਮਾਰੇ: 'a hundred along with' or 'struck with Sat (Truth)'; uncertain."},{"gurmukhi":"ਭਈ ਧੀਰ ਧਰਮੰ ਬ੍ਰਹਮ ਗਿਆਨ ਤਾਰੇ। ੩੧੩।","roman":"Bhaee dheer dharman braham giaan taare | 313 |","meaning_en":"Dhir (Steadfastness) and Dharam took heart, and Brahm Gyan (Knowledge of God) brought them through.","page":908,"meaning_status":"draft","note":"Uncertain line."}]},{"type":"verse","number":[314],"number_text":"੩੧੪।","page":908,"lines":[{"gurmukhi":"ਕਈ ਬਾਣ ਕੁਲਹਤ੍ਰਤਾ ਕੋ ਚਲਾਏ।","roman":"Kaee baan kulahtrataa ko chalaae |","meaning_en":"He loosed several arrows at Kulhatrata (Slaying of Kin);","page":908,"meaning_status":"draft","note":"ਕੁਲਹਤ੍ਰਤਾ: read as 'killing one's own family'; uncertain."},{"gurmukhi":"ਕਈ ਬਾਣ ਲੈ ਬੈਰ ਕੇ ਬੀਰ ਘਾਏ।","roman":"Kaee baan lai bair ke beer ghaae |","meaning_en":"taking several arrows, he wounded the warriors of Bair (Enmity);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਘਾਇ ਆਲਸ ਕੈ ਅੰਗਿ ਲਾਗੇ।","roman":"Kite ghaai aalas kai angi laage |","meaning_en":"many wounds struck the body of Alas (Sloth);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਸਬੈ ਨਰਕ ਤੇ ਆਦਿ ਲੈ ਬੀਰ ਭਾਗੇ। ੩੧੪।","roman":"Sabai narak te aadi lai beer bhaage | 314 |","meaning_en":"all the warriors, Narak (Hell) and the rest, fled.","page":908,"meaning_status":"draft"}]},{"type":"verse","number":[315],"number_text":"੩੧੫।","page":908,"lines":[{"gurmukhi":"ਇਕੈ ਬਾਣ ਨਿਸੀਲ ਕੋ ਅੰਗ ਛੇਦ੍ਯੋ।","roman":"Ikai baan niseel ko ang chhedyo |","meaning_en":"With one arrow he pierced the body of Nisil (Bad Character);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਦੁਤੀ ਕੁਸਤਤਾ ਕੋ ਭਲੈ ਸੂਤ ਭੇਦ੍ਯੋ।","roman":"Dutee kusattaa ko bhalai soot bhedyo |","meaning_en":"with a second he struck the charioteer of Kustata (Foulness);","page":908,"meaning_status":"draft"},{"gurmukhi":"ਗੁਮਾਨਾਦਿ ਕੇ ਚਾਰ ਬਾਜੀ ਸੰਘਾਰੇ।","roman":"Gumaanaadi ke chaar baajee sanghaare |","meaning_en":"he slew the four horses of Guman (Pride) and the others;","page":908,"meaning_status":"draft"},{"gurmukhi":"ਅਨਰਥਾਦਿ ਕੇ ਬੀਰ ਬਾਂਕੇ ਨਿਵਾਰੇ। ੩੧੫।","roman":"Anarthaadi ke beer baanke nivaare | 315 |","meaning_en":"he drove off the bold warriors of Anarath (Wrongdoing) and the rest.","page":908,"meaning_status":"draft"}]},{"type":"verse","number":[316],"number_text":"੩੧੬।","page":909,"lines":[{"gurmukhi":"ਪਿਪਾਸਾ ਛੁਧਾ ਆਲਸਾਦੀ ਪਰਾਨੇ।","roman":"Pipaasaa chhudhaa aalsaadee paraane |","meaning_en":"Pipasa (Thirst), Chhudha (Hunger), Alas (Sloth) and the others fled;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਭਜ੍ਯੋ ਲੋਭ ਕ੍ਰੋਧੀ ਹਠੀ ਦੇਵ ਜਾਨੇ।","roman":"Bhajyo lobh krodhee hathee dev jaane |","meaning_en":"Lobh fled, and stubborn Krodh, as the gods saw;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਤਪ੍ਯੋ ਨੇਮ ਨਾਮਾ ਅਨੇਮੰ ਪ੍ਰਣਾਸੀ।","roman":"Tapyo nem naamaa aneman pranaasee |","meaning_en":"the one named Nem (Discipline), destroyer of Anem (Indiscipline), blazed forth;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਧਰੇ ਜੋਗ ਅਸਤ੍ਰੰ ਅਲੋਭੀ ਉਦਾਸੀ। ੩੧੬।","roman":"Dhare jog astran alobhee udaasee | 316 |","meaning_en":"Alobhi (the Non-greedy) and Udasi (the Detached) took up the weapon of yoga.","page":909,"meaning_status":"draft"}]},{"type":"verse","number":[317],"number_text":"੩੧੭।","page":909,"lines":[{"gurmukhi":"ਹਤ੍ਯੋ ਕਾਪਟੰ ਖਾਪਟੰ ਸੋਕ ਪਾਲੰ।","roman":"Hatyo kaaptan khaaptan sok paalan |","meaning_en":"He slew Kapat (Deceit), Khapat, and Sokpal (Keeper of Sorrow);","page":909,"meaning_status":"draft","note":"ਖਾਪਟੰ: obscure, perhaps a rhyming companion of ਕਾਪਟੰ; uncertain."},{"gurmukhi":"ਹਨ੍ਯੋ ਰੋਹ ਮੋਹੰ ਸਕਾਮੰ ਕਰਾਲੰ।","roman":"Hanyo roh mohan sakaaman karaalan |","meaning_en":"he slew Roh (Fury), Moh (Attachment) and dreadful Sakam (Desire);","page":909,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਕ੍ਰੁਧ ਕੈ ਕ੍ਰੋਧ ਕੋ ਬਾਨ ਮਾਰ੍ਯੋ।","roman":"Mahaa krudh kai krodh ko baan maaryo |","meaning_en":"in great anger he shot an arrow at Krodh (Anger);","page":909,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਖਿਸ੍ਯੋ ਬ੍ਰਹਮ ਦੋਖਦਿ ਸਰਬੰ ਪ੍ਰਹਾਰ੍ਯੋ। ੩੧੭।","roman":"Khisyo braham dokhdi sarban prahaaryo | 317 |","meaning_en":"Brahmdokh (Offence against Brahmins) and the others slipped back, and he struck them all.","page":909,"meaning_status":"draft","note":"Uncertain line."}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Ruaal metre.","page":909,"meaning_status":"draft"},{"type":"verse","number":[318],"number_text":"੩੧੮।","page":909,"lines":[{"gurmukhi":"ਸੁ ਦ੍ਰੋਹ ਅਉ ਹੰਕਾਰ ਕੋ ਹਜਾਰ ਬਾਨ ਸੋ ਹਨ੍ਯੋ।","roman":"Su droh au hankaar ko hajaar baan so hanyo |","meaning_en":"He struck Droh (Treachery) and Hankar (Ego) with a thousand arrows;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਦਰਿਦ੍ਰ ਅਸੰਕ ਮੋਹ ਕੋ ਨ ਚਿਤ ਮੈ ਕਛ ਗਨ੍ਯੋ।","roman":"Daridr asank moh ko na chit mai kachh ganyo |","meaning_en":"Daridra (Poverty), Asank and Moh (Attachment) he counted as nothing at all;","page":909,"meaning_status":"draft","note":"ਅਸੰਕ: obscure; uncertain."},{"gurmukhi":"ਅਸੋਚ ਅਉ ਕੁਮੰਤ੍ਰਤਾ ਅਨੇਕ ਬਾਨ ਸੋ ਹਤ੍ਯੋ।","roman":"Asoch au kumantrataa anek baan so hatyo |","meaning_en":"he struck Asoch (Thoughtlessness) and Kumantrata (Evil Counsel) with many arrows;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਕਲੰਕ ਨਿਸੰਕ ਹ੍ਵੈ ਸਹੰਸ੍ਰ ਸਾਇਕੰ ਛਤ੍ਯੋ। ੩੧੮।","roman":"Kalank nisank hvai sahansr saaikan chhatyo | 318 |","meaning_en":"without fear he pierced Kalank (Stain) with a thousand arrows.","page":909,"meaning_status":"draft"}]},{"type":"verse","number":[319],"number_text":"੩੧੯।","page":909,"lines":[{"gurmukhi":"ਕ੍ਰਿਤਘਨਤਾ ਬਿਸ੍ਵਾਸਘਾਤ ਮਿਤ੍ਰਘਾਤ ਮਾਰ੍ਯੋ।","roman":"Kritghantaa bisvaasghaat mitraghaat maaryo |","meaning_en":"He slew Kritghanta (Ingratitude), Bisvasghat (Betrayal of Trust) and Mitraghat (Betrayal of Friends);","page":909,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਰਾਜ ਦੋਖ ਬ੍ਰਹਮ ਦੋਖ ਬ੍ਰਹਮ ਅਸਤ੍ਰ ਝਾਰ੍ਯੋ।","roman":"Su raaj dokh braham dokh braham asatr jhaaryo |","meaning_en":"he struck Rajdokh (Offence against the King) and Brahmdokh (Offence against Brahmins) with the Brahm missile;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਉਚਾਟ ਮਾਰਣਾਦਿ ਬਸਿਕਰਣ ਕੋ ਸਾਰ ਹਨ੍ਯੋ।","roman":"Uchaat maarnaadi basikran ko saar hanyo |","meaning_en":"he struck down Uchat, Maran and the other spells, and Basikaran, with steel;","page":909,"meaning_status":"draft","note":"Uchat, Maran, Basikaran: tantric rites to distract, kill and enthral."},{"gurmukhi":"ਬਿਖਾਧ ਕੋ ਬਿਖਾਧ ਕੈ ਨ ਬ੍ਰਿਧ ਤਾਹਿ ਕੋ ਗਨ੍ਯੋ। ੩੧੯।","roman":"Bikhaadh ko bikhaadh kai na bridh taahi ko ganyo | 319 |","meaning_en":"he made Bikhadh (Grief) grieve, and did not count him great.","page":909,"meaning_status":"draft","note":"Uncertain line."}]},{"type":"verse","number":[320],"number_text":"੩੨੦।","page":909,"lines":[{"gurmukhi":"ਭਜੇ ਰਥੀ ਹਈ ਗਈ ਸੁ ਪਤਿ ਤ੍ਰਾਸ ਧਾਰਿ ਕੈ।","roman":"Bhaje rathee haee gaee su pati traas dhaari kai |","meaning_en":"Chariot-riders, horsemen, elephant-riders and foot soldiers fled in terror;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਭਜੇ ਰਥੀ ਮਹਾਰਥੀ ਸੁ ਲਾਜ ਕੋ ਬਿਸਾਰਿ ਕੈ।","roman":"Bhaje rathee mahaarthee su laaj ko bisaari kai |","meaning_en":"chariot-warriors and great chariot-warriors fled, forgetting shame.","page":909,"meaning_status":"draft"},{"gurmukhi":"ਅਸੰਭ ਜੁਧ ਜੋ ਭਯੋ ਸੁ ਕੈਸ ਕੇ ਬਤਾਈਐ।","roman":"Asanbh judh jo bhayo su kais ke bataaeeai |","meaning_en":"How can the immense battle that took place be told?","page":909,"meaning_status":"draft"},{"gurmukhi":"ਸਹੰਸ ਬਾਕ ਜੋ ਰਟੈ ਨ ਤਤ੍ਰ ਪਾਰ ਪਾਈਐ। ੩੨੦।","roman":"Sahans baak jo ratai na tatr paar paaeeai | 320 |","meaning_en":"Even if one recited it with a thousand tongues, one would not reach its end.","page":909,"meaning_status":"draft"}]},{"type":"verse","number":[321],"number_text":"੩੨੧।","page":909,"lines":[{"gurmukhi":"ਕਲੰਕ ਬਿਭ੍ਰਮਾਦਿ ਅਉ ਕ੍ਰਿਤਘਨ ਤਾਹਿ ਕੌ ਹਨ੍ਯੋ।","roman":"Kalank bibhramaadi au kritghan taahi kau hanyo |","meaning_en":"He slew Kalank (Stain), Bibhram (Delusion) and the rest, and Kritghan (Ingratitude);","page":909,"meaning_status":"draft"},{"gurmukhi":"ਬਿਖਾਦ ਬਿਪਦਾਦਿ ਕੋ ਕਛ ਨ ਚਿਤ ਮੈ ਗਨ੍ਯੋ।","roman":"Bikhaad bipdaadi ko kachh na chit mai ganyo |","meaning_en":"Bikhad (Grief), Bipada (Misfortune) and the others he counted as nothing;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਮਿਤ੍ਰਦੋਖ ਰਾਜਦੋਖ ਈਰਖਾਹਿ ਮਾਰਿ ਕੈ।","roman":"Su mitradokh raajdokh eerkhaahi maari kai |","meaning_en":"slaying Mitradokh (Offence against Friends), Rajdokh and Irkha (Envy),","page":909,"meaning_status":"draft"},{"gurmukhi":"ਉਚਾਟ ਅਉ ਬਿਖਾਧ ਕੋ ਦਯੋ ਰਣੰ ਨਿਕਾਰਿ ਕੈ। ੩੨੧।","roman":"Uchaat au bikhaadh ko dayo ranan nikaari kai | 321 |","meaning_en":"he drove Uchat (Distraction) and Bikhadh (Grief) out of the battle.","page":909,"meaning_status":"draft"}]},{"type":"verse","number":[322],"number_text":"੩੨੨।","page":909,"lines":[{"gurmukhi":"ਗਿਲਾਨਿ ਕੋਪ ਮਾਨ ਅਪ੍ਰਮਾਨ ਬਾਨ ਸੋ ਹਨ੍ਯੋ।","roman":"Gilaani kop maan apramaan baan so hanyo |","meaning_en":"He struck Gilani (Self-loathing), Kop (Wrath) and Man (Pride) with countless arrows;","page":909,"meaning_status":"draft","note":"ਗਿਲਾਨਿ: 'remorse, aversion'."},{"gurmukhi":"ਅਨਰਥ ਕੋ ਸਮਰਥ ਕੈ ਹਜਾਰ ਬਾਨ ਸੋ ਝਨ੍ਯੋ।","roman":"Anrath ko samrath kai hajaar baan so jhanyo |","meaning_en":"with full might he struck Anarath (Wrongdoing) with a thousand arrows;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਕੁਚਾਰ ਕੋ ਹਜਾਰ ਬਾਨ ਚਾਰ ਸੋ ਪ੍ਰਹਾਰ੍ਯੋ।","roman":"Kuchaar ko hajaar baan chaar so prahaaryo |","meaning_en":"he struck Kuchar (Misconduct) with four thousand arrows;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਕੁਕਸਟ ਅਉ ਕੁਕ੍ਰਿਆ ਕੌ ਭਜਾਇ ਤ੍ਰਾਸੁ ਡਾਰ੍ਯੋ। ੩੨੨।","roman":"Kuksat au kukriaa kau bhajaai traasu daaryo | 322 |","meaning_en":"he put Kukasht (Hardship) and Kukria (Evil Deeds) to flight, filling them with dread.","page":909,"meaning_status":"draft","note":"ਕੁਕਸਟ: uncertain."}]},{"type":"heading","kind":"chhand","name":"ਛਪਯ ਛੰਦ","gurmukhi":"ਛਪਯ ਛੰਦ","roman":"Chhapay chhand","meaning_en":"Chhappay metre.","page":909,"meaning_status":"draft"},{"type":"verse","number":[323],"number_text":"੩੨੩।","page":909,"lines":[{"gurmukhi":"ਅਤਪ ਬੀਰ ਕਉ ਤਾਕਿ ਬਾਨ ਸਤਰਿ ਮਾਰੇ ਤਪ।","roman":"Atap beer kau taaki baan satri maare tap |","meaning_en":"Aiming at the warrior Atap (Non-austerity), Tap (Austerity) shot seventy arrows;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਨਵੇ ਸਾਇਕਨਿ ਸੀਲ ਸਹਸ ਸਰ ਹਨੈ ਅਜਪ ਜਪ।","roman":"Nave saaikni seel sahas sar hanai ajap jap |","meaning_en":"Sil (Good Character) struck with ninety arrows, and Jap (Recitation) struck Ajap (Non-recitation) with a thousand;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਬੀਸ ਬਾਣ ਕੁਮਤਹਿ ਤੀਸ ਕੁਕਰਮਹਿ ਭੇਦ੍ਯੋ।","roman":"Bees baan kumathi tees kukramhi bhedyo |","meaning_en":"he pierced Kumat (Evil Mind) with twenty arrows and Kukaram (Evil Deeds) with thirty;","page":909,"meaning_status":"draft"},{"gurmukhi":"ਦਸ ਸਾਇਕ ਦਾਰਿਦ੍ਰ ਕਾਮ ਕਈ ਬਾਣਨਿ ਛੇਦ੍ਯੋ।","roman":"Das saaik daaridr kaam kaee baanni chhedyo |","meaning_en":"with ten arrows he pierced Daridra (Poverty), and Kam (Lust) with several arrows;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਬਿਧਿ ਬਿਰੋਧ ਕੋ ਬਧ ਕੀਯੋ ਅਬਿਬੇਕਹਿ ਸਰ ਸੰਧਿ ਰਣਿ।","roman":"Bahu bidhi birodh ko badh keeyo abibekhi sar sandhi rani |","meaning_en":"in many ways he slew Birodh (Hostility), fitting arrows against Abibek in the battle;","page":910,"meaning_status":"draft","note":"Who fits the arrows is unclear; uncertain."},{"gurmukhi":"ਰਣਿ ਰੋਹ ਕ੍ਰੋਹ ਕਰਵਾਰ ਗਹਿ ਇਮ ਸੰਜਮ ਬੁਲ੍ਯੋ ਬਯਣ। ੩੨੩।","roman":"Rani roh kroh karvaar gahi im sanjam bulyo bayan | 323 |","meaning_en":"in the battle, in fury and wrath, grasping his sword, Sanjam (Self-restraint) spoke these words:","page":910,"meaning_status":"draft"}]},{"type":"verse","number":[324],"number_text":"੩੨੪।","page":910,"lines":[{"gurmukhi":"ਅਰੁਣ ਪਛਮਹਿ ਉਗ੍ਵੈ ਬਰੁਣੁ ਉਤਰ ਦਿਸ ਤਕੈ।","roman":"Arun pachhamhi ugvai barunu utar dis takai |","meaning_en":"'The sun may rise in the west, and Varun look to the north;","page":910,"meaning_status":"draft","note":"ਅਰੁਣ: the dawn/sun."},{"gurmukhi":"ਮੇਰੁ ਪੰਖ ਕਰਿ ਉਡੇ ਸਰਬ ਸਾਇਰ ਜਲ ਸੁਕੈ।","roman":"Meru pankh kari ude sarab saair jal sukai |","meaning_en":"Mount Meru may grow wings and fly, and the waters of all the oceans dry up;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਕੋਲ ਦਾੜ ਕੜਮੁੜੈ ਸਿਮਟਿ ਫਨੀਅਰ ਫਣ ਫਟੈ।","roman":"Kol daar karmurai simti phaneear phan phatai |","meaning_en":"the Boar's tusks may crack, and the serpent's hoods shrink and split;","page":910,"meaning_status":"draft","note":"ਕੋਲ: the Boar (Varah) who bears the earth; ਫਨੀਅਰ: the serpent Shesh."},{"gurmukhi":"ਉਲਟਿ ਜਾਨ੍ਹਵੀ ਬਹੈ ਸਤ ਹਰੀਚੰਦੇ ਹਟੈ।","roman":"Ulti jaanhavee bahai sat hareechande hatai |","meaning_en":"the Ganga may flow backwards, and Harichand abandon truth;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਸੰਸਾਰ ਉਲਟ ਪੁਲਟ ਹ੍ਵੈ ਧਸਕਿ ਧਉਲ ਧਰਣੀ ਫਟੈ।","roman":"Sansaar ulat pulat hvai dhaski dhaul dharnee phatai |","meaning_en":"the world may be turned upside down, the bull (that bears the earth) sink, and the earth split apart:","page":910,"meaning_status":"draft","note":"ਧਉਲ: the mythical bull supporting the earth."},{"gurmukhi":"ਸੁਨਿ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਸੁ ਬਿਬੇਕ ਭਟਿ ਤਦਪਿ ਨ ਲਟਿ ਸੰਜਮ ਹਟੈ।੩੨੪।","roman":"Suni nrip abibek su bibek bhati tadpi na lati sanjam hatai | 324 |","meaning_en":"listen, King Abibek, even then Sanjam, warrior of Bibek, will not retreat.'","page":910,"meaning_status":"draft","note":"ਲਟਿ: uncertain."}]},{"type":"heading","kind":"chhand","name":"ਤੇਰੇ ਜੋਰਿ ਮੈ ਗੁੰਗਾ ਕਹਤਾ ਹੋ ਤੇਰਾ ਸਦਕਾ ਤੇਰੀ ਸਰਣਿ","gurmukhi":"ਤੇਰੇ ਜੋਰਿ ਮੈ ਗੁੰਗਾ ਕਹਤਾ ਹੋ ਤੇਰਾ ਸਦਕਾ ਤੇਰੀ ਸਰਣਿ","roman":"Tere jori mai gungaa kahtaa ho teraa sadkaa teree sarni","meaning_en":"By Your power I, a mute, speak; by Your grace; in Your refuge.","page":910,"meaning_status":"draft","note":"An invocation set between verses in the text, not part of the narrative."},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":910,"meaning_status":"draft"},{"type":"verse","number":[325],"number_text":"੩੨੫।","page":910,"lines":[{"gurmukhi":"ਕੁਪ੍ਯੋ ਸੰਜਮੰ ਪਰਮ ਜੋਧਾ ਜੁਝਾਰੰ।","roman":"Kupyo sanjman param jodhaa jujhaaran |","meaning_en":"Sanjam (Self-restraint), the supreme fighting warrior, grew angry,","page":910,"meaning_status":"draft"},{"gurmukhi":"ਬਡੋ ਗਰਬਧਾਰੀ ਬਡੋ ਨਿਰਬਿਕਾਰੰ।","roman":"Bado garabdhaaree bado nirbikaaran |","meaning_en":"very proud and wholly flawless;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤਾਸਤ੍ਰ ਲੈ ਕੈ ਅਨਰਥੈ ਪ੍ਰਹਾਰ੍ਯੋ।","roman":"Anantaasatr lai kai anarthai prahaaryo |","meaning_en":"taking countless missiles, he struck Anarath (Wrongdoing),","page":910,"meaning_status":"draft"},{"gurmukhi":"ਅਨਾਦਤ ਕੇ ਅੰਗ ਕੋ ਛੇਦ ਡਾਰ੍ਯੋ। ੩੨੫।","roman":"Anaadat ke ang ko chhed daaryo | 325 |","meaning_en":"and cut apart the body of Anadat.","page":910,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੇਰੇ ਜੋਰਿ ਕਹਤ ਹੋ","gurmukhi":"ਤੇਰੇ ਜੋਰਿ ਕਹਤ ਹੋ","roman":"Tere jori kahat ho","meaning_en":"By Your power I speak.","page":910,"meaning_status":"draft","note":"An invocation set between verses."},{"type":"verse","number":[326],"number_text":"੩੨੬।","page":910,"lines":[{"gurmukhi":"ਇਸੋ ਜੁਧੁ ਬੀਤ੍ਯੋ ਕਹਾ ਲੌ ਸੁਨਾਊ।","roman":"Iso judhu beetyo kahaa lau sunaaoo |","meaning_en":"Such a battle took place; how far can I tell of it?","page":910,"meaning_status":"draft"},{"gurmukhi":"ਰਟੋ ਸਹੰਸ ਜਿਹਵਾ ਨ ਤਉ ਅੰਤ ਪਾਊ।","roman":"Rato sahans jihvaa na tau ant paaoo |","meaning_en":"Even if I recited it with a thousand tongues, I would not reach its end.","page":910,"meaning_status":"draft"},{"gurmukhi":"ਦਸੰ ਲਛ ਜੁਗ੍ਯੰ ਸੁ ਬਰਖੰ ਅਨੰਤੰ।","roman":"Dasan lachh jugyan su barkhan anantan |","meaning_en":"For ten lakh ages and endless years","page":910,"meaning_status":"draft"},{"gurmukhi":"ਭਯੋ ਬੀਰਖੇਤੰ ਕਥੈ ਕਉਣ ਖੰਤੰ। ੩੨੬।","roman":"Bhayo beerkhetan kathai kaun khantan | 326 |","meaning_en":"the battlefield raged; who can tell it to the end?","page":910,"meaning_status":"draft","note":"ਖੰਤੰ: uncertain."}]},{"type":"heading","kind":"chhand","name":"ਤੇਰੇ ਜੋਰ ਸੰਗ ਕਹਤਾ ਹੈ","gurmukhi":"ਤੇਰੇ ਜੋਰ ਸੰਗ ਕਹਤਾ ਹੈ","roman":"Tere jor sang kahtaa hai","meaning_en":"With Your power (the poet) speaks.","page":910,"meaning_status":"draft","note":"An invocation set between verses."},{"type":"verse","number":[327],"number_text":"੩੨੭।","page":910,"lines":[{"gurmukhi":"ਭਈ ਅੰਧ ਧੁੰਧੰ ਮਚ੍ਯੋ ਬੀਰ ਖੇਤੰ।","roman":"Bhaee andh dhundhan machyo beer khetan |","meaning_en":"Blinding darkness fell, and battle raged on the field of heroes;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਨਚੀ ਜੁਗਣੀ ਚਾਰੁ ਚਉਸਠ ਪ੍ਰੇਤੰ।","roman":"Nachee jugnee chaaru chausath pretan |","meaning_en":"the lovely yoginis and the sixty-four spirits danced;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਨਚੀ ਕਾਲਕਾ ਸ੍ਰੀ ਕਮਖ੍ਯਾ ਕਰਾਲੰ।","roman":"Nachee kaalkaa sree kamkhyaa karaalan |","meaning_en":"Kalka and the dreadful, revered Kamakhya danced;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਡਕੰ ਡਾਕਣੀ ਜੋਧ ਜਾਗੰਤ ਜ੍ਵਾਲੰ। ੩੨੭।","roman":"Dakan daaknee jodh jaagant jvaalan | 327 |","meaning_en":"the dakinis shrieked, and the warriors blazed like flame.","page":910,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੇਰਾ ਜੋਰੁ","gurmukhi":"ਤੇਰਾ ਜੋਰੁ","roman":"Teraa joru","meaning_en":"Your power.","page":910,"meaning_status":"draft","note":"An invocation set between verses."},{"type":"verse","number":[328],"number_text":"੩੨੮।","page":910,"lines":[{"gurmukhi":"ਮਚ੍ਯੋ ਜੋਰ ਜੁਧੰ ਹਟ੍ਯੋ ਨਾਹਿ ਕੋਊ।","roman":"Machyo jor judhan hatyo naahi ko'oo |","meaning_en":"Fierce battle raged and no one drew back,","page":910,"meaning_status":"draft"},{"gurmukhi":"ਬਡੇ ਛਤ੍ਰਧਾਰੀ ਪਤੀ ਛਤ੍ਰ ਦੋਊ।","roman":"Bade chhatradhaaree patee chhatr do'oo |","meaning_en":"both of them great bearers of canopies, lords of the royal canopy;","page":910,"meaning_status":"draft"},{"gurmukhi":"ਖਪ੍ਯੋ ਸਰਬ ਲੋਕੰ ਅਲੋਕੰ ਅਪਾਰੰ।","roman":"Khapyo sarab lokan alokan apaaran |","meaning_en":"all the worlds and the boundless realms beyond were worn out,","page":910,"meaning_status":"draft"},{"gurmukhi":"ਮਿਟੇ ਜੁਧ ਤੇ ਏ ਨ ਜੋਧਾ ਜੁਝਾਰੰ। ੩੨੮।","roman":"Mite judh te e na jodhaa jujhaaran | 328 |","meaning_en":"yet these fighting warriors were not ended by the war.","page":910,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੇਰਾ ਜੋਰ","gurmukhi":"ਤੇਰਾ ਜੋਰ","roman":"Teraa jor","meaning_en":"Your power.","page":911,"meaning_status":"draft","note":"An invocation set between verses."},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":911,"meaning_status":"draft"},{"type":"verse","number":[329],"number_text":"੩੨੯।","page":911,"lines":[{"gurmukhi":"ਚਟਪਟ ਸੁਭਟ ਬਿਕਟ ਕਟੇ ਝਟਪਟ ਭਈ ਅਭੰਗ।","roman":"Chatpat subhat bikat kate jhatpat bhaee abhang |","meaning_en":"In a flash formidable warriors were cut down; swiftly the unbroken fight went on;","page":911,"meaning_status":"draft"},{"gurmukhi":"ਲਟਿ ਭਟ ਹਟੇ ਨ ਰਨ ਘਟ੍ਯੋ ਅਟਪਟ ਮਿਟ੍ਯੋ ਨ ਜੰਗ। ੩੨੯।","roman":"Lati bhat hate na ran ghatyo atpat mityo na jang | 329 |","meaning_en":"the warriors did not draw back, the fighting did not lessen, and the tangled war did not end.","page":911,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੇਰੇ ਜੋਰਿ","gurmukhi":"ਤੇਰੇ ਜੋਰਿ","roman":"Tere jori","meaning_en":"By Your power.","page":911,"meaning_status":"draft","note":"An invocation set between verses."},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":911,"meaning_status":"draft"},{"type":"verse","number":[330],"number_text":"੩੩੦।","page":911,"lines":[{"gurmukhi":"ਬੀਸ ਲਛ ਜੁਗ ਐਤੁ ਪ੍ਰਮਾਨਾ। ਲਰੇ ਦੋਊ ਭਈ ਕਿਸ ਨ ਹਾਨਾ।","roman":"Bees lachh jug aitu pramaanaa | lare do'oo bhaee kis na haanaa |","meaning_en":"For a full twenty lakh ages the two fought, and neither suffered loss.","page":911,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਰਾਜਾ ਜੀਅ ਮੈ ਅਕੁਲਾਯੋ। ਨਾਕ ਚਢੇ ਮਛਿੰਦ੍ਰ ਪੈ ਆਯੋ। ੩੩੦।","roman":"Tab raajaa jeea mai akulaayo | naak chadhe machhindr pai aayo | 330 |","meaning_en":"Then the king grew troubled at heart and, frowning, came to Machhindra.","page":911,"meaning_status":"draft","note":"The king is Parasnath. ਨਾਕ ਚਢੇ: lit. 'with nose raised', displeased."}]},{"type":"verse","number":[331],"number_text":"੩੩੧।","page":911,"lines":[{"gurmukhi":"ਕਹਿ ਮੁਨਿ ਬਰਿ ਸਭ ਮੋਹਿ ਬਿਚਾਰਾ। ਏ ਦੋਊ ਬੀਰ ਬਡੇ ਬਰਿਆਰਾ।","roman":"Kahi muni bari sabh mohi bichaaraa | e do'oo beer bade bariaaraa |","meaning_en":"'Tell me, great sage, after thinking it all over: these two heroes are very mighty;","page":911,"meaning_status":"draft"},{"gurmukhi":"ਇਨ ਕਾ ਬਿਰੁਧ ਨਿਵਰਤ ਨ ਭਯਾ। ਇਨੋ ਛਡਾਵਤ ਸਭ ਜਗੁ ਗਯਾ। ੩੩੧।","roman":"In kaa birudh nivrat na bhayaa | ino chhadaavat sabh jagu gayaa | 331 |","meaning_en":"their enmity has never ceased; the whole world has passed away trying to part them;","page":911,"meaning_status":"draft"}]},{"type":"verse","number":[332],"number_text":"੩੩੨।","page":911,"lines":[{"gurmukhi":"ਇਨੈ ਜੁਝਾਵਤ ਸਬ ਕੋਈ ਜੂਝਾ। ਇਨ ਕਾ ਅੰਤ ਨ ਕਾਹੂ ਸੂਝਾ।","roman":"Inai jujhaavat sab koee joojhaa | in kaa ant na kaahoo soojhaa |","meaning_en":"all who set them fighting have perished in the fight, and no one has understood their end;","page":911,"meaning_status":"draft"},{"gurmukhi":"ਏ ਹੈ ਆਦਿ ਹਠੀ ਬਰਿਆਰਾ। ਮਹਾਰਥੀ ਅਉ ਮਹਾ ਭਯਾਰਾ। ੩੩੨।","roman":"E hai aadi hathee bariaaraa | mahaarthee au mahaa bhayaaraa | 332 |","meaning_en":"they are primal, stubborn and mighty, great chariot-warriors and very dreadful.'","page":911,"meaning_status":"draft"}]},{"type":"verse","number":[333],"number_text":"੩੩੩।","page":911,"lines":[{"gurmukhi":"ਬਚਨੁ ਮਛਿੰਦ੍ਰ ਸੁਨਤ ਚੁਪ ਰਹਾ। ਧਰਾ ਨਾਥ ਸਬਨਨ ਤਨ ਕਹਾ।","roman":"Bachnu machhindr sunat chup rahaa | dharaa naath sabnan tan kahaa |","meaning_en":"Hearing these words, Machhindra stayed silent; the lord of the earth spoke to them all.","page":911,"meaning_status":"draft"},{"gurmukhi":"ਚਕ੍ਰਿਤ ਚਿਤ ਚਟਪਟ ਹ੍ਵੈ ਦਿਖਸਾ। ਚਰਪਟ ਨਾਥ ਤਦਿਨ ਤੇ ਨਿਕਸਾ। ੩੩੩।","roman":"Chakrit chit chatpat hvai dikhsaa | charpat naath tadin te niksaa | 333 |","meaning_en":"His mind astonished, he looked about in a flash; from that day Charpat Nath came forth.","page":911,"meaning_status":"draft","note":"Who looked about is unclear; uncertain."}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ‘ਚਰਪਟ ਨਾਥ’ ਪ੍ਰਗਟਣੋ ਨਾਮਹ।","roman":"Iti ‘charpat naath’ pragatno naamah |","meaning_en":"Here ends the chapter named 'The appearance of Charpat Nath'.","page":911,"meaning_status":"draft"}],"page":911}});
